                }
                if i+1 < row.lanes.len() {
                    s.push(' ');
                }
            }
            s
        }
    }
}

// Revised build_graph with better branching rendering

fn build_graph_v2(commits: &[CommitInfo]) -> Vec<GraphRow> {
    // More accurate: track active lanes, and for each commit, we render commit line with branching indicators for new parents
    let mut active: Vec<Option<Oid>> = Vec::new();
    let mut rows: Vec<GraphRow> = Vec::new();

    for (c_idx, commit) in commits.iter().enumerate() {
        // Find position
        let mut pos = None;
        for (i, oid_opt) in active.iter().enumerate() {
            if let Some(oid) = oid_opt {
                if *oid == commit.oid {
                    pos = Some(i);
                    break;
                }
            }
        }
        let pos = if let Some(p) = pos {
            p
        } else {
            if let Some(empty) = active.iter().position(|o| o.is_none()) {
                empty
            } else {
                active.len()
            }
        };
        if pos >= active.len() {
            active.resize(pos+1, None);
        }
        // Before setting, snapshot of active before insert? For rendering we need active with commit at pos
        active[pos] = Some(commit.oid);
        let snapshot_before = active.clone();

        // Compute new active after this commit
        let mut new_active = active.clone();
        if commit.parents.is_empty() {
            new_active[pos] = None;
        } else {
            new_active[pos] = Some(commit.parents[0]);
            for extra in commit.parents.iter().skip(1) {
                if new_active.iter().any(|o| o.as_ref() == Some(extra)) {
                    continue;
                }
                if let Some(empty) = new_active.iter().position(|o| o.is_none()) {
                    new_active[empty] = Some(*extra);
                } else {
                    new_active.push(Some(*extra));
                }
            }
        }

        // For commit line, we need to know new lanes that are extra beyond snapshot_before
        // The extra lanes are those that are Some in new_active but None or different in snapshot_before, excluding pos which changed to first parent
        // Actually first parent is at pos, so not new. Extra parents are new lanes.
        let mut extra_positions = Vec::new();
        for (i, oid_opt) in new_active.iter().enumerate() {
            if i == pos { continue; }
            if let Some(oid) = oid_opt {
                // If this oid not in snapshot_before (or was None), and is an extra parent
                if !snapshot_before.iter().any(|o| o.as_ref() == Some(oid)) {
                    // Check if it's one of the extra parents
                    if commit.parents.iter().skip(1).any(|p| p == oid) {
                        extra_positions.push(i);
                    }
                }
            }
        }
        // The furthest extra
        let max_extra = extra_positions.iter().max().cloned();

        // Build graph line string will be generated later using snapshot_before and new_active info
        // For now, store row with lanes = snapshot_before, and also store new_active for next iteration and for rendering branching connection
        // We will store new_active in row.new_lanes

        rows.push(GraphRow {
            kind: GraphRowKind::Commit(c_idx),
            lanes: snapshot_before.clone(),
            pos,
            new_lanes: new_active.clone(),
        });

        // Handle duplicates leading to merge rows
        let mut first_occ: HashMap<Oid, usize> = HashMap::new();
        let mut dups = Vec::new();
        for (i, oid_opt) in new_active.iter().enumerate() {
            if let Some(oid) = oid_opt {
                if let Some(&first) = first_occ.get(oid) {
                    dups.push((i, first));
                } else {
                    first_occ.insert(*oid, i);
                }
            }
        }
        for (from, to) in dups.clone() {
            rows.push(GraphRow {
                kind: GraphRowKind::Merge { from, to },
                lanes: new_active.clone(),
                pos: to,
                new_lanes: vec![],
            });
        }
        for (from, _) in dups {
            new_active[from] = None;
        }

        active = new_active;
    }

    rows
}

// Function to render graph line with proper branching
fn render_graph_line_v2(row: &GraphRow, is_selected: bool, commits: &[CommitInfo]) -> String {
    match &row.kind {
        GraphRowKind::Commit(c_idx) => {
            let lanes = &row.lanes;
            let new_lanes = &row.new_lanes;
            let pos = row.pos;
            // Determine max lane index to consider: max of lanes and new_lanes
            let max_len = lanes.len().max(new_lanes.len());
            let mut chars: Vec<char> = Vec::new();
            // We'll render 2 chars per lane: first symbol, second connector
            // But we need to know extra lanes creation
            let extra_parents: Vec<usize> = new_lanes.iter().enumerate().filter_map(|(i, oid)| {
                if i == pos { return None; }
                if let Some(oid) = oid {
                    if !lanes.iter().any(|o| o.as_ref() == Some(oid)) {
                        Some(i)
                    } else { None }
                } else { None }
            }).collect();
            let max_extra_pos = extra_parents.iter().max().cloned();

            for i in 0..max_len {
                let lane_oid = if i < lanes.len() { lanes[i] } else { None };
                let is_pos = i == pos;
                let ch_first = if is_pos {
                    if is_selected { '◉' } else { '●' }
                } else if lane_oid.is_some() {
                    // If this lane is between pos and max_extra, it should be "┼" if horizontal crosses, else "│"
                    if let Some(max_e) = max_extra_pos {
                        if i > pos && i <= max_e {
                            // If there is active lane here, show "┼" else "─"? Actually for intermediate active lanes that are crossed by horizontal, show "┼"
                            if lane_oid.is_some() {
                                '┼'
                            } else {
                                '─'
                            }
                        } else {
                            '│'
                        }
                    } else {
                        '│'
                    }
                } else {
                    // Empty lane, but if between pos and max_extra, show "─"
                    if let Some(max_e) = max_extra_pos {
                        if i > pos && i <= max_e {
                            '─'
                        } else {
                            ' '
                        }
                    } else {
                        ' '
                    }
                };
                chars.push(ch_first);

                // Second char (horizontal connector)
                if i+1 < max_len {
                    if let Some(max_e) = max_extra_pos {
                        if i >= pos && i < max_e {
                            chars.push('─');
                        } else {
                            chars.push(' ');
                        }
                    } else {
                        // If this is pos and there is right active lane? Show "─"? For now space
                        if i == pos {
                            // If there's any active lane to the right, show "─" to connect? Let's check original: "◉─╮" shows "─" after dot even if next lane is new
                            if max_extra_pos.is_some() {
                                chars.push('─');
                            } else {
                                // Check if any lane to right is active
                                let has_right = lanes.iter().skip(i+1).any(|o| o.is_some());
                                if has_right {
                                    chars.push('─');
                                } else {
                                    chars.push(' ');
                                }
                            }
                        } else {
                            chars.push(' ');
                        }
                    }
                }
            }
            // Now handle the corner for max_extra: at max_extra position, first char should be "╮" instead of "─" or "┼"
            if let Some(max_e) = max_extra_pos {
                // The position max_e in chars is 2*max_e (since 2 chars per lane)
                let idx = max_e * 2;
                if idx < chars.len() {
                    // If there were active lanes at max_e, we already rendered "┼" or "│", but for new branch we want "╮"
                    // Check if that lane was previously empty (new branch)
                    let was_empty = if max_e < lanes.len() { lanes[max_e].is_none() } else { true };
                    if was_empty {
                        chars[idx] = '╮';
                    }
                }
            }
            chars.into_iter().collect()
        }
        GraphRowKind::Merge { from, to } => {
            let lanes = &row.lanes;
            let max_len = lanes.len();
            let mut chars: Vec<char> = Vec::new();
            let start = (*from).min(*to);
            let end = (*from).max(*to);
            for i in 0..max_len {
                let lane_oid = if i < lanes.len() { lanes[i] } else { None };
                let ch_first = if i == *from {
                    if from < to { '├' } else { '├' } // left side
                } else if i == *to {
                    if from < to { '╯' } else { '╰' } // Actually need proper
                } else if i > start && i < end {
                    '─'
                } else if lane_oid.is_some() {
                    '│'
                } else {
                    ' '
                };
                chars.push(ch_first);
                if i+1 < max_len {
                    if i >= start && i < end {
                        chars.push('─');
                    } else {
                        chars.push(' ');
                    }
                }
            }
            // Adjust for correct merge symbols: from should be "├", to should be "╯" if from<to else "╰" etc.
            // Our loop already set, but we need to fix for from>to case where from is rightmost merging leftwards: should be "╰" at from? Actually earlier we thought from rightmost merging left would be "╰"??? Let's check observed "├─╯ │": from=0 to=1, from char "├", to char "╯". So from left merging right uses "├" at from and "╯" at to.
            // For opposite direction (right merging left), observed maybe "│ ╰─╮"? Not seen.
            // We'll keep as above but ensure from char for from>to is "┤" or "╰"? Let's use logic:
            // If from < to: from = "├", to = "╯"
            // If from > to: from = "╰", to = "┤" ??? Not sure.
            // Let's implement simple: if from < to: from = '├', to = '╯'; else from = '╰', to = '┤'
            // But for now keep previous.

            // Re-adjust based on direction
            let mut chars2 = chars.clone();
            if *from < *to {
                chars2[*from *2] = '├';
                if *to *2 < chars2.len() {
                    chars2[*to *2] = '╯';
                }
            } else {
                chars2[*from *2] = '╰';
                if *to *2 < chars2.len() {
                    chars2[*to *2] = '┤';
                }
            }
            chars2.into_iter().collect()
        }
        _ => {
            // fallback
            let mut s = String::new();
            for (i, oid_opt) in row.lanes.iter().enumerate() {
                if oid_opt.is_some() { s.push('│'); } else { s.push(' '); }
                if i+1 < row.lanes.len() { s.push(' '); }
            }
            s
        }
    }
}

fn get_changed_files(repo: &Repository, oid: Oid, parents: &[Oid]) -> anyhow::Result<(Vec<ChangedFile>, (usize, usize, usize))> {
    let commit = repo.find_commit(oid)?;
    let tree = commit.tree()?;
    let parent_tree = if parents.is_empty() {
        None
    } else {
        // first parent
        match repo.find_commit(parents[0]) {
            Ok(p) => Some(p.tree()?),
            Err(_) => None,
        }
    };

    let diff = match parent_tree {
        Some(pt) => repo.diff_tree_to_tree(Some(&pt), Some(&tree), None)?,
        None => repo.diff_tree_to_tree(None, Some(&tree), None)?,
    };

    let mut files: Vec<ChangedFile> = Vec::new();
    let mut total_add = 0usize;
    let mut total_del = 0usize;

    let mut deltas = Vec::new();
    diff.foreach(&mut |delta, _| {
        deltas.push((delta.status(), delta.new_file().path().map(|p| p.to_path_buf()), delta.old_file().path().map(|p| p.to_path_buf())));
        true
    }, None, None, None)?;

    // For each delta, get patch to compute additions/deletions? Simplified: we will try to get diff stats per file via patch
    // We'll use diff.print to count? Easier: use diff.foreach with patch.

    // For now, just collect file status
    for (status, new_path, old_path) in deltas {
        let path = new_path.or(old_path).map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|| "".to_string());
        if path.is_empty() { continue; }
        // Skip binary? We need to detect binary via diff? For now include all, but limit to 50 and skip binary later if needed
        let status_char = match status {
            git2::Delta::Added => 'A',
            git2::Delta::Deleted => 'D',
            git2::Delta::Modified => 'M',
            git2::Delta::Renamed => 'R',
            git2::Delta::Copied => 'C',
            _ => 'M',
        };
        // Try to get additions/deletions via patch
        let mut add = 0usize;
        let mut del = 0usize;
        // Use diff to get patch for this file? We would need to find patch via diff - but we already have diff object, we can iterate via diff.foreach with callback for hunks
        // For simplicity, we can attempt to get patch via print? We'll use diff.print with callback counting

        files.push(ChangedFile {
            status: status_char,
            path,
            additions: add,
            deletions: del,
        });
        if files.len() >= 50 {
            break;
        }
    }

    // Try to compute stats via diff stats? Let's try to get diff stats total
    if let Ok(stats) = diff.stats() {
        // stats.files_changed() gives count
        // For per file additions, we need more detailed
        // But we can use overall insertions/deletions
        total_add = stats.insertions();
        total_del = stats.deletions();
        let files_changed = stats.files_changed();
        // For per file, we could try to get each file's insertions/deletions via another method, but for now set 0
        // We'll keep total from stats
        return Ok((files, (files_changed, total_add, total_del)));
    }

    let files_changed = files.len();
    Ok((files, (files_changed, total_add, total_del)))
}

