fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 {
        match args[1].as_str() {
            "-h" | "--help" => {
                println!("A TUI tool to visualize Git commit graphs with branch genealogy\n\nUsage: executable\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("keifu 0.2.3");
                std::process::exit(0);
            }
            _ => {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable\n\nFor more information, try '--help'.", args[1]);
                std::process::exit(2);
            }
        }
    }

    // Check tty
    if !crossterm::tty::IsTty::is_tty(&std::io::stdout()) {
        eprintln!("Error: No such device or address (os error 6)");
        std::process::exit(1);
    }

    // Check git repo
    let repo = match Repository::discover(".") {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: Git repository not found. Please run inside a Git repository.\n\nCaused by:\n    {}", e);
            std::process::exit(1);
        }
    };

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    let app = App::new(repo)?;
    let res = run_app(&mut terminal, app);

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Error: {}", err);
        std::process::exit(1);
    }

    Ok(())
}

fn run_app<B: ratatui::backend::Backend>(terminal: &mut ratatui::Terminal<B>, mut app: App) -> anyhow::Result<()> {
    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        // Handle auto-refresh
        if app.config.auto_refresh {
            if app.last_refresh.elapsed() >= Duration::from_secs(app.config.refresh_interval) {
                let _ = app.refresh();
                app.last_refresh = Instant::now();
            }
        }
        if app.config.auto_fetch {
            if app.last_fetch.elapsed() >= Duration::from_secs(app.config.fetch_interval) {
                app.fetch_origin();
                app.last_fetch = Instant::now();
            }
        }

        // Clear expired status
        if let Some((_, instant, _)) = &app.status_msg {
            if instant.elapsed() > Duration::from_secs(5) {
                app.status_msg = None;
            }
        }

        if event::poll(Duration::from_millis(200))? {
            if let Event::Key(key) = event::read()? {
                match app.mode {
                    Mode::Normal => {
                        if app.help_visible {
                            match key.code {
                                KeyCode::Char('?') | KeyCode::Esc | KeyCode::Char('q') => {
                                    app.help_visible = false;
                                }
                                _ => {}
                            }
                            continue;
                        }
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                return Ok(());
                            }
                            KeyCode::Char('j') | KeyCode::Down => {
                                app.move_down();
                            }
                            KeyCode::Char('k') | KeyCode::Up => {
                                app.move_up();
                            }
                            KeyCode::Char('g') | KeyCode::Home => {
                                app.go_top();
                            }
                            KeyCode::Char('G') | KeyCode::End => {
                                app.go_bottom();
                            }
                            KeyCode::Char('@') => {
                                app.jump_to_head();
                            }
                            KeyCode::Char(']') | KeyCode::Tab => {
                                app.next_branch_commit();
                            }
                            KeyCode::Char('[') => {
                                app.prev_branch_commit();
                            }
                            KeyCode::BackTab => {
                                app.prev_branch_commit();
                            }
                            KeyCode::Char('h') | KeyCode::Left => {
                                app.select_left_branch();
                            }
                            KeyCode::Char('l') | KeyCode::Right => {
                                app.select_right_branch();
                            }
                            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.page_down();
                            }
                            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.page_up();
                            }
                            KeyCode::Char('R') => {
                                let _ = app.refresh();
                                app.set_status("Refreshed".to_string(), false);
                            }
                            KeyCode::Char('?') => {
                                app.help_visible = true;
                            }
                            KeyCode::Char('/') => {
                                app.mode = Mode::Search;
                                app.search_query.clear();
                                app.search_selected = 0;
                                // Reset search results to all branches
                                // Already have all branches in search_results? Actually refresh filled.
                                // Filter
                            }
                            KeyCode::Char('b') => {
                                app.mode = Mode::NewBranch;
                                app.new_branch_input.clear();
                            }
                            KeyCode::Char('d') => {
                                if let Some(branch) = app.get_selected_branch() {
                                    if branch.is_remote {
                                        app.set_status("Cannot delete remote branch".to_string(), true);
                                    } else {
                                        app.mode = Mode::DeleteConfirm;
                                        app.delete_confirm_branch = Some(branch);
                                    }
                                }
                            }
                            KeyCode::Char('f') => {
                                app.fetch_origin();
                            }
                            KeyCode::Enter => {
                                app.checkout_selected();
                            }
                            _ => {}
                        }
                    }
                    Mode::Search => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = Mode::Normal;
                                app.search_query.clear();
                            }
                            KeyCode::Enter => {
                                if let Some(branch) = app.search_results.get(app.search_selected).cloned() {
                                    // Jump to branch's commit
                                    if let Some(idx) = app.commits.iter().position(|c| c.oid == branch.oid) {
                                        app.selected_commit_idx = idx;
                                        let _ = app.update_changed_files();
                                        // Also select that branch within commit
                                        if let Some(pos) = app.commits[idx].branches.iter().position(|b| b.name == branch.name && b.is_remote == branch.is_remote) {
                                            app.selected_branch_per_commit.insert(branch.oid, pos);
                                        }
                                    }
                                }
                                app.mode = Mode::Normal;
                            }
                            KeyCode::Up => {
                                if app.search_selected > 0 {
                                    app.search_selected -=1;
                                }
                            }
                            KeyCode::Down => {
                                if app.search_selected +1 < app.search_results.len() {
                                    app.search_selected +=1;
                                }
                            }
                            KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if app.search_selected >0 { app.search_selected-=1; }
                            }
                            KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if app.search_selected+1 < app.search_results.len() { app.search_selected+=1; }
                            }
                            KeyCode::Backspace => {
                                if app.search_query.is_empty() {
                                    app.mode = Mode::Normal;
                                } else {
                                    app.search_query.pop();
                                    // filter
                                    let query = app.search_query.clone();
                                    // Need all branches list: we have search_results currently filtered? We need original all branches list - we stored all branches in search_results initially, but after filtering we lose. So we need to store all branches separately.
                                    // For now, we will refilter from commits branches
                                    let mut all_branches: Vec<BranchInfo> = Vec::new();
                                    let mut seen = HashSet::new();
                                    for c in &app.commits {
                                        for b in &c.branches {
                                            if seen.insert((b.name.clone(), b.is_remote)) {
                                                all_branches.push(b.clone());
                                            }
                                        }
                                    }
                                    if query.is_empty() {
                                        app.search_results = all_branches;
                                    } else {
                                        app.search_results = all_branches.into_iter().filter(|b| fuzzy_match(&query, &b.name)).collect();
                                    }
                                    app.search_selected = 0;
                                }
                            }
                            KeyCode::Char(c) => {
                                app.search_query.push(c);
                                let query = app.search_query.clone();
                                let mut all_branches: Vec<BranchInfo> = Vec::new();
                                let mut seen = HashSet::new();
                                for commit in &app.commits {
                                    for b in &commit.branches {
                                        if seen.insert((b.name.clone(), b.is_remote)) {
                                            all_branches.push(b.clone());
                                        }
                                    }
                                }
                                if query.is_empty() {
                                    app.search_results = all_branches;
                                } else {
                                    app.search_results = all_branches.into_iter().filter(|b| fuzzy_match(&query, &b.name)).collect();
                                }
                                app.search_selected = 0;
                            }
                            _ => {}
                        }
                    }
                    Mode::NewBranch => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = Mode::Normal;
                            }
                            KeyCode::Enter => {
                                let name = app.new_branch_input.clone();
                                app.mode = Mode::Normal;
                                app.create_branch(&name);
                            }
                            KeyCode::Backspace => {
                                app.new_branch_input.pop();
                            }
                            KeyCode::Char(c) => {
                                app.new_branch_input.push(c);
                            }
                            _ => {}
                        }
                    }
                    Mode::DeleteConfirm => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = Mode::Normal;
                                app.delete_confirm_branch = None;
                            }
                            KeyCode::Enter => {
                                if let Some(branch) = app.delete_confirm_branch.take() {
                                    app.delete_branch(branch);
                                }
                                app.mode = Mode::Normal;
                            }
                            _ => {}
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    // Layout: vertical: commits, bottom (detail + files), status bar
    let vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(12), Constraint::Length(1)])
        .split(size);

    let commits_area = vertical[0];
    let bottom_area = vertical[1];
    let status_area = vertical[2];

    let bottom_horizontal = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(bottom_area);

    let commit_detail_area = bottom_horizontal[0];
    let changed_files_area = bottom_horizontal[1];

    // Commits block
    let commits_block = Block::default()
        .title(" Commits ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner_commits = commits_block.inner(commits_area);
    f.render_widget(commits_block, commits_area);

    // Render commits list
    // Determine width for graph and info
    // For each graph row, render

    // To simplify, we'll render commit lines only, not merge rows, but we have merge rows for visual.
    // Our graph_rows includes both commit and merge rows. However selected_commit_idx maps to commits vec, not graph_rows.
    // We need to render graph rows that are within scroll view, but highlight selected commit row.

    // Determine scroll offset to keep selected visible
    // Find graph index of selected commit
    let selected_graph_idx = if app.commits.is_empty() {
        0
    } else {
        let oid = app.commits[app.selected_commit_idx].oid;
        *app.commit_to_graph_idx.get(&oid).unwrap_or(&0)
    };

    // Ensure selected is visible: adjust graph_scroll
    let visible_height = inner_commits.height as usize;
    if selected_graph_idx < app.graph_scroll {
        app.graph_scroll = selected_graph_idx;
    } else if selected_graph_idx >= app.graph_scroll + visible_height {
        app.graph_scroll = selected_graph_idx - visible_height + 1;
    }

    // Build lines for commits area
    let mut lines_to_render: Vec<Line> = Vec::new();
    let mut colors_palette = vec![Color::Blue, Color::Green, Color::Magenta, Color::Cyan, Color::Yellow, Color::LightRed, Color::LightGreen, Color::LightBlue];
    // Assign color per lane oid? For simplicity assign per lane index cycling

    for (row_idx, graph_row) in app.graph_rows.iter().enumerate().skip(app.graph_scroll).take(visible_height) {
        // Determine if this row is commit row and if selected
        let is_selected_commit = match &graph_row.kind {
            GraphRowKind::Commit(c_idx) => *c_idx == app.selected_commit_idx,
            _ => false,
        };

        let graph_str = render_graph_line_v2(graph_row, is_selected_commit, &app.commits);

        // If commit row, add commit info
        let line = if let GraphRowKind::Commit(c_idx) = &graph_row.kind {
            let commit = &app.commits[*c_idx];
            // Branch label
            let branch_label = if commit.branches.is_empty() {
                "".to_string()
            } else {
                let sel_branch_idx = app.selected_branch_per_commit.get(&commit.oid).cloned().unwrap_or(0);
                let sel_branch = &commit.branches[sel_branch_idx.min(commit.branches.len()-1)];
                // Check if there's a pair local + remote same name
                // Find if commit has local and remote with same base name
                // For simplicity, if selected branch is local and there's remote with same name stripped origin/, show "↔ origin"
                let has_pair = {
                    let base = if sel_branch.is_remote {
                        if sel_branch.name.starts_with("origin/") {
                            sel_branch.name.trim_start_matches("origin/").to_string()
                        } else { sel_branch.name.clone() }
                    } else {
                        sel_branch.name.clone()
                    };
                    // Look for counterpart
                    let mut has_local = false;
                    let mut has_remote = false;
                    for b in &commit.branches {
                        let b_base = if b.is_remote {
                            if b.name.starts_with("origin/") { b.name.trim_start_matches("origin/").to_string() } else { b.name.clone() }
                        } else { b.name.clone() };
                        if b_base == base {
                            if b.is_remote { has_remote = true; } else { has_local = true; }
                        }
                    }
                    has_local && has_remote && commit.branches.len() == 2 // Only show ↔ when exactly 2 and they are pair? But earlier we had 2 branches pair
                    // For more general, if selected is local and remote exists with same base, show ↔
                };
                let extra_count = commit.branches.len() -1;
                if commit.branches.len() > 1 {
                    // Check pair case
                    let sel_base = if sel_branch.is_remote {
                        if sel_branch.name.starts_with("origin/") { sel_branch.name.trim_start_matches("origin/").to_string() } else { sel_branch.name.clone() }
                    } else { sel_branch.name.clone() };
                    let mut counterpart_exists = false;
                    for b in &commit.branches {
                        if b.is_remote != sel_branch.is_remote {
                            let b_base = if b.is_remote {
                                if b.name.starts_with("origin/") { b.name.trim_start_matches("origin/").to_string() } else { b.name.clone() }
                            } else { b.name.clone() };
                            if b_base == sel_base {
                                counterpart_exists = true;
                                break;
                            }
                        }
                    }
                    if counterpart_exists {
                        if extra_count ==1 {
                            format!("[{} ↔ origin]", sel_base)
                        } else {
                            format!("[{} ↔ origin] +{}", sel_base, extra_count-1)
                        }
                    } else {
                        format!("[{}] +{}", sel_branch.name, extra_count)
                    }
                } else {
                    // Single branch
                    // Check if it's remote only, show as [origin/xxx] ? Already name includes origin/
                    // For pair where 2 branches but we want ↔, we already handled above single extra count ==1 case?
                    // Actually if commit has 2 branches that are pair, extra_count=1 and counterpart_exists true, we should show ↔ without + 
                    // For single branch case, counterpart check not applicable
                    // But for 2 branches pair, our earlier branch len >1 handling will have triggered, so we are good
                    // For single branch:
                    if commit.branches.len() ==1 {
                        // If this single branch is part of pair? No, pair needs 2 branches
                        format!("[{}]", sel_branch.name)
                    } else {
                        format!("[{}]", sel_branch.name)
                    }
                }
            };

            // Message, date, author, hash
            let date_str = commit.committer_date.format("%Y-%m-%d").to_string();
            let author = commit.author_name.clone();
            let hash = commit.short.clone();

            // Available width for commit info after graph
            // graph_str width approx lanes*2, let's compute its display width (assuming 1 char per column, but unicode width maybe 1)
            let graph_width = graph_str.chars().count() + 2; // plus spaces
            let inner_width = inner_commits.width as usize;
            let remaining = inner_width.saturating_sub(graph_width);

            // Construct line content
            // We'll reserve for right side: date 10 + space, author maybe up to 10? hash 7
            // For simplicity, if remaining < 20, only show message truncated
            let mut info_part = String::new();
            if !branch_label.is_empty() {
                info_part.push_str(&branch_label);
                info_part.push(' ');
            }
            info_part.push_str(&commit.message);

            // Right align date/author/hash if space
            // We'll build spans

            // For now, build a single string with info plus right-aligned
            let mut right_part = String::new();
            if inner_width >= 100 {
                right_part = format!(" {}  {}  {}", date_str, author, hash);
            } else if inner_width >= 80 {
                right_part = format!(" {}  {}", date_str, author);
            } else {
                // No right part
            }

            // Truncate info_part if needed to fit
            let right_len = right_part.chars().count();
            let max_info_len = remaining.saturating_sub(right_len).saturating_sub(2);
            let truncated_info = if info_part.chars().count() > max_info_len {
                let mut s: String = info_part.chars().take(max_info_len.saturating_sub(1)).collect();
                if max_info_len>0 { s.push('…'); }
                s
            } else { info_part };

            let full_line = format!("{}  {}{}", graph_str, truncated_info, right_part);

            // Style: if selected, highlight background? Original had selected line with maybe bold and background dark?
            // We'll use style
            let mut spans = Vec::new();
            // Graph part colored? We'll color graph dots per lane color
            // For simplicity, add graph as span with colors per char? We'll just use default
            // We'll attempt to color graph chars based on lane index colors
            // Build spans for graph part char by char with color
            for (i, ch) in graph_str.chars().enumerate() {
                let color = colors_palette[i % colors_palette.len()];
                // Dot colors?
                spans.push(Span::styled(ch.to_string(), Style::default().fg(color)));
            }
            spans.push(Span::raw("  "));
            // Branch label color?
            if !branch_label.is_empty() {
                spans.push(Span::styled(branch_label, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)));
                spans.push(Span::raw(" "));
            }
            spans.push(Span::raw(commit.message.clone()));

            // Right part aligned to right? We can pad spaces
            let info_len = truncated_info.chars().count() + branch_label.chars().count() + 1 + graph_width;
            let padding = inner_width.saturating_sub(info_len).saturating_sub(right_len);
            spans.push(Span::raw(" ".repeat(padding)));
            if !right_part.is_empty() {
                // date, author, hash with styles
                // We'll split right_part into date, author, hash
                // For simplicity, raw
                spans.push(Span::styled(right_part, Style::default().fg(Color::DarkGray)));
            }

            let mut line = Line::from(spans);
            if is_selected_commit {
                line = line.style(Style::default().bg(Color::DarkGray).add_modifier(Modifier::BOLD));
            }
            line
        } else {
            // Merge row, just graph
            let mut spans = Vec::new();
            for (i, ch) in graph_str.chars().enumerate() {
                let color = colors_palette[i % colors_palette.len()];
                spans.push(Span::styled(ch.to_string(), Style::default().fg(color)));
            }
            Line::from(spans)
        };
        lines_to_render.push(line);
    }

    let paragraph = Paragraph::new(lines_to_render);
    f.render_widget(paragraph, inner_commits);

    // Commit Detail
    let detail_block = Block::default()
        .title(" Commit Detail ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));
    let inner_detail = detail_block.inner(commit_detail_area);
    f.render_widget(detail_block, commit_detail_area);

    if app.commits.is_empty() {
        let p = Paragraph::new("Select a commit");
        f.render_widget(p, inner_detail);
    } else {
        let commit = &app.commits[app.selected_commit_idx];
        let parent_str = if commit.parents.is_empty() {
            "".to_string()
        } else {
            commit.parents.iter().map(|oid| format!("{:.7}", oid.to_string())).collect::<Vec<_>>().join(", ")
        };
        let mut text_lines = vec![
            Line::from(vec![Span::styled("Commit: ", Style::default().add_modifier(Modifier::BOLD)), Span::styled(commit.oid.to_string(), Style::default().fg(Color::Yellow))]),
            Line::from(vec![Span::styled("Author: ", Style::default().add_modifier(Modifier::BOLD)), Span::styled(format!("{} <{}>", commit.author_name, commit.author_email), Style::default().fg(Color::Blue))]),
            Line::from(vec![Span::styled("Date:   ", Style::default().add_modifier(Modifier::BOLD)), Span::raw(commit.author_date.format("%Y-%m-%d %H:%M:%S").to_string())]),
            Line::from(vec![Span::styled("Parent: ", Style::default().add_modifier(Modifier::BOLD)), Span::raw(parent_str)]),
            Line::from(""),
            Line::from(commit.full_message.clone()),
        ];
        let p = Paragraph::new(text_lines);
        f.render_widget(p, inner_detail);
    }

    // Changed Files
    let changed_block = Block::default()
        .title(" Changed Files ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));
    let inner_changed = changed_block.inner(changed_files_area);
    f.render_widget(changed_block, changed_files_area);

    let (files_changed, adds, dels) = app.changed_stats;
    let header = format!("{} files changed  +{} -{}", files_changed, adds, dels);
    let mut cf_lines = vec![
        Line::from(vec![Span::styled(header, Style::default().add_modifier(Modifier::BOLD)), Span::raw(format!("  "))]),
        Line::from(""),
    ];
    for file in &app.changed_files {
        let line = format!(" {} {} +{} -{}", file.status, file.path, file.additions, file.deletions);
        cf_lines.push(Line::from(line));
        if cf_lines.len() > 50 { break; }
    }
    let p = Paragraph::new(cf_lines);
    f.render_widget(p, inner_changed);

    // Status bar
    let repo_name = app.repo_name.clone();
    let branch_name = app.current_branch.clone();
    let mut status_spans = Vec::new();
    status_spans.push(Span::styled(format!(" {} ", repo_name), Style::default().bg(Color::Magenta).fg(Color::Black).add_modifier(Modifier::BOLD)));
    status_spans.push(Span::raw(" "));
    status_spans.push(Span::styled(format!(" {} ", branch_name), Style::default().bg(Color::Green).fg(Color::Black)));
    status_spans.push(Span::raw(" "));

    if let Some((msg, _, is_err)) = &app.status_msg {
        let style = if *is_err { Style::default().bg(Color::Red).fg(Color::White) } else { Style::default().bg(Color::Blue).fg(Color::White) };
        status_spans.push(Span::styled(format!(" {} ", msg), style));
        status_spans.push(Span::raw(" "));
        status_spans.push(Span::styled(if *is_err { " ERROR" } else { " INFO" }, Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)));
    } else {
        if app.help_visible {
            status_spans.push(Span::styled(" Esc/q close help ", Style::default()));
            status_spans.push(Span::raw(" ".repeat(10)));
            status_spans.push(Span::styled(" HELP", Style::default().bg(Color::Yellow).fg(Color::Black).add_modifier(Modifier::BOLD)));
        } else {
            match app.mode {
                Mode::Normal => {
                    status_spans.push(Span::styled(" j/k ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("move "));
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("checkout "));
                    status_spans.push(Span::styled(" b ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("branch "));
                    status_spans.push(Span::styled(" f ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("fetch "));
                    status_spans.push(Span::styled(" ? ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("help "));
                    status_spans.push(Span::styled(" q ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("quit"));
                }
                Mode::Search => {
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("confirm "));
                    status_spans.push(Span::styled(" Esc ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("cancel"));
                    status_spans.push(Span::raw(" ".repeat(10)));
                    status_spans.push(Span::styled(" INPUT", Style::default().bg(Color::Yellow).fg(Color::Black).add_modifier(Modifier::BOLD)));
                }
                Mode::NewBranch => {
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("confirm "));
                    status_spans.push(Span::styled(" Esc ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("cancel"));
                    status_spans.push(Span::raw(" ".repeat(10)));
                    status_spans.push(Span::styled(" INPUT", Style::default().bg(Color::Yellow).fg(Color::Black).add_modifier(Modifier::BOLD)));
                }
                Mode::DeleteConfirm => {
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("confirm "));
                    status_spans.push(Span::styled(" Esc ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("cancel"));
                }
                _ => {}
            }
        }
    }

    let status_line = Line::from(status_spans);
    let status_paragraph = Paragraph::new(status_line);
    f.render_widget(status_paragraph, status_area);

    // Popups
    if app.help_visible {
        let area = centered_rect(60, 70, size);
        f.render_widget(Clear, area);
        let block = Block::default()
            .title(" Help ")
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::Cyan));
        let inner = block.inner(area);
        f.render_widget(block, area);

        let help_text = vec![
            Line::from(Span::styled("Navigation", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  j / ↓      Move down"),
            Line::from("  k / ↑      Move up"),
            Line::from("  ] / Tab    Select next branch"),
            Line::from("  [ / S-Tab  Select previous branch"),
            Line::from("  h / ←      Select left branch (same commit)"),
            Line::from("  l / →      Select right branch (same commit)"),
            Line::from("  Ctrl+d     Page down"),
            Line::from("  Ctrl+u     Page up"),
            Line::from("  g / Home   Go to top"),
            Line::from("  G / End    Go to bottom"),
            Line::from("  @          Jump to HEAD (current branch)"),
            Line::from(""),
            Line::from(Span::styled("Git Operations", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  Enter      Checkout selected branch/commit"),
            Line::from("  b          Create new branch"),
            Line::from("  d          Delete branch"),
            Line::from("  f          Fetch from origin"),
            Line::from(""),
            Line::from(Span::styled("Search", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  /          Search branches"),
            Line::from("  ↑ / C-k    Select previous result"),
            Line::from("  ↓ / C-j    Select next result"),
            Line::from("  Enter      Jump to selected branch"),
            Line::from("  Esc        Cancel search"),
            Line::from(""),
            Line::from(Span::styled("Other", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  R          Refresh"),
            Line::from("  ?          Toggle this help"),
            Line::from("  q / Esc    Quit"),
        ];
        let p = Paragraph::new(help_text);
        f.render_widget(p, inner);
    }

    match app.mode {
        Mode::Search => {
            let area = centered_rect(60, 40, size);
            f.render_widget(Clear, area);
            let block = Block::default()
                .title(" Search branches ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Cyan));
            let inner = block.inner(area);
            f.render_widget(block, area);

            let vertical = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Length(3), Constraint::Min(0)])
                .split(inner);

            let input = format!("{}_", app.search_query);
            let input_paragraph = Paragraph::new(input)
                .block(Block::default().borders(Borders::BOTTOM));
            f.render_widget(input_paragraph, vertical[0]);

            let mut items: Vec<ListItem> = Vec::new();
            for (i, branch) in app.search_results.iter().enumerate() {
                let style = if i == app.search_selected { Style::default().bg(Color::DarkGray) } else { Style::default() };
                let prefix = if i == app.search_selected { "▶ " } else { "  " };
                items.push(ListItem::new(format!("{}{}", prefix, branch.name)).style(style));
            }
            let list = List::new(items)
                .block(Block::default().title(format!(" {} branches ", app.search_results.len())));
            f.render_widget(list, vertical[1]);
        }
        Mode::NewBranch => {
            let area = centered_rect(60, 20, size);
            f.render_widget(Clear, area);
            let block = Block::default()
                .title(" New Branch Name ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Cyan));
            let inner = block.inner(area);
            f.render_widget(block, area);

            let input = format!("{}_", app.new_branch_input);
            let vertical = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Length(3), Constraint::Length(1)])
                .split(inner);
            let p = Paragraph::new(input);
            f.render_widget(p, vertical[0]);
            let hint = Paragraph::new("  Enter: confirm  Esc: cancel");
            f.render_widget(hint, vertical[1]);
        }
        Mode::DeleteConfirm => {
            if let Some(branch) = &app.delete_confirm_branch {
                let area = centered_rect(60, 20, size);
                f.render_widget(Clear, area);
                let block = Block::default()
                    .title(" Delete Branch ")
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(Color::Red));
                let inner = block.inner(area);
                f.render_widget(block, area);

                let text = vec![
                    Line::from(format!("Delete branch '{}'?", branch.name)),
                    Line::from(""),
                    Line::from("  Enter: confirm  Esc: cancel"),
                ];
                let p = Paragraph::new(text);
                f.render_widget(p, inner);
            }
        }
        _ => {}
    }

    // Branch selection dropdown when multiple branches at same commit
    if app.mode == Mode::Normal && !app.help_visible {
        if !app.commits.is_empty() {
            let commit = &app.commits[app.selected_commit_idx];
            if commit.branches.len() > 1 {
                // Show popup with branches list near commit
                // Position: near top? We'll place at center right? Original showed near commit line on right side.
                // For simplicity, place at top right of commits area
                let area = Rect {
                    x: commits_area.x + commits_area.width.saturating_sub(20),
                    y: commits_area.y + 2,
                    width: 18,
                    height: (commit.branches.len() as u16 + 2).min(10),
                };
                f.render_widget(Clear, area);
                let block = Block::default()
                    .title(" Branches ")
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(Color::Cyan));
                let inner = block.inner(area);
                f.render_widget(block, area);
                let sel_idx = app.selected_branch_per_commit.get(&commit.oid).cloned().unwrap_or(0);
                let items: Vec<ListItem> = commit.branches.iter().enumerate().map(|(i, b)| {
                    let prefix = if i == sel_idx { "▶ " } else { "  " };
                    ListItem::new(format!("{}{}", prefix, b.name))
                }).collect();
                let list = List::new(items);
                f.render_widget(list, inner);
            }
        }
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}
