use std::collections::{HashMap, HashSet};
use serde::Deserialize;
use std::time::{Duration, Instant};

#[derive(Debug, Deserialize, Default)]
struct ConfigFile {
    refresh: Option<RefreshConfig>,
}
#[derive(Debug, Deserialize)]
struct RefreshConfig {
    auto_refresh: Option<bool>,
    refresh_interval: Option<u64>,
    auto_fetch: Option<bool>,
    fetch_interval: Option<u64>,
}

struct AppConfig {
    auto_refresh: bool,
    refresh_interval: u64,
    auto_fetch: bool,
    fetch_interval: u64,
}
impl Default for AppConfig {
    fn default() -> Self {
        Self {
            auto_refresh: true,
            refresh_interval: 10,
            auto_fetch: true,
            fetch_interval: 60,
        }
    }
}
fn load_config() -> AppConfig {
    let mut cfg = AppConfig::default();
    if let Some(dir) = dirs::config_dir() {
        let path = dir.join("keifu").join("config.toml");
        if let Ok(content) = std::fs::read_to_string(&path) {
            if let Ok(file) = toml::from_str::<ConfigFile>(&content) {
                if let Some(r) = file.refresh {
                    if let Some(v) = r.auto_refresh {
                        cfg.auto_refresh = v;
                    }
                    if let Some(v) = r.refresh_interval {
                        cfg.refresh_interval = v.max(1);
                    }
                    if let Some(v) = r.auto_fetch {
                        cfg.auto_fetch = v;
                    }
                    if let Some(v) = r.fetch_interval {
                        cfg.fetch_interval = v.max(10);
                    }
                }
            }
        }
    }
    cfg
}

#[derive(Clone, Debug)]
struct BranchInfo {
    name: String, // e.g., "main" or "origin/main"
    full_ref: String, // refs/heads/main or refs/remotes/origin/main
    is_remote: bool,
    is_head: bool,
    oid: Oid,
}

#[derive(Clone, Debug)]
struct CommitInfo {
    oid: Oid,
    short: String,
    message: String, // first line
    full_message: String,
    author_name: String,
    author_email: String,
    author_date: DateTime<Local>,
    committer_date: DateTime<Local>,
    parents: Vec<Oid>,
    branches: Vec<BranchInfo>, // branches pointing at this oid
}

#[derive(Clone, Debug)]
struct ChangedFile {
    status: char, // M, A, D, etc
    path: String,
    additions: usize,
    deletions: usize,
}

#[derive(Clone, Debug)]
enum GraphRowKind {
    Commit(usize), // index into commits
    Merge { from: usize, to: usize }, // from lane to to lane
    Junction, // generic junction? We'll use Merge for simplicity
}

#[derive(Clone, Debug)]
struct GraphRow {
    kind: GraphRowKind,
    lanes: Vec<Option<Oid>>, // snapshot of active lanes before this row? For rendering
    pos: usize, // commit position if commit
    new_lanes: Vec<Option<Oid>>, // after
}

struct App {
    repo_path: PathBuf,
    repo_name: String,
    current_branch: String,
    head_oid: Option<Oid>,
    commits: Vec<CommitInfo>,
    graph_rows: Vec<GraphRow>,
    // Mapping from commit oid to graph row index for commit
    commit_to_graph_idx: HashMap<Oid, usize>,
    selected_commit_idx: usize,
    // per commit selected branch index
    selected_branch_per_commit: HashMap<Oid, usize>,
    // overall scroll offset for commits pane (graph rows offset)
    graph_scroll: usize,
    // commit detail scroll? not needed
    changed_files: Vec<ChangedFile>,
    changed_stats: (usize, usize, usize), // files, add, del
    // Modes
    mode: Mode,
    help_visible: bool,
    search_query: String,
    search_results: Vec<BranchInfo>,
    search_selected: usize,
    new_branch_input: String,
    delete_confirm_branch: Option<BranchInfo>,
    error_msg: Option<String>,
    status_msg: Option<(String, Instant, bool)>, // bool is error?
    config: AppConfig,
    last_refresh: Instant,
    last_fetch: Instant,
    repo: Repository,
}

#[derive(Clone, Debug, PartialEq)]
enum Mode {
    Normal,
    Search,
    NewBranch,
    DeleteConfirm,
    Help,
}

impl App {
    fn new(repo: Repository) -> anyhow::Result<Self> {
        let repo_path = repo.path().parent().unwrap_or_else(|| std::path::Path::new(".")).to_path_buf();
        let repo_name = repo_path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "repo".to_string());
        let config = load_config();
        let mut app = App {
            repo_path,
            repo_name,
            current_branch: String::new(),
            head_oid: None,
            commits: Vec::new(),
            graph_rows: Vec::new(),
            commit_to_graph_idx: HashMap::new(),
            selected_commit_idx: 0,
            selected_branch_per_commit: HashMap::new(),
            graph_scroll: 0,
            changed_files: Vec::new(),
            changed_stats: (0,0,0),
            mode: Mode::Normal,
            help_visible: false,
            search_query: String::new(),
            search_results: Vec::new(),
            search_selected: 0,
            new_branch_input: String::new(),
            delete_confirm_branch: None,
            error_msg: None,
            status_msg: None,
            config,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            repo,
        };
        app.refresh()?;
        Ok(app)
    }

    fn refresh(&mut self) -> anyhow::Result<()> {
        // Reopen repo to get fresh data
        self.repo = Repository::discover(&self.repo_path)?;
        self.current_branch = match self.repo.head() {
            Ok(head) => {
                if head.is_branch() {
                    head.shorthand().unwrap_or("HEAD").to_string()
                } else {
                    // detached
                    "HEAD".to_string()
                }
            }
            Err(_) => "".to_string(),
        };
        self.head_oid = self.repo.head().ok().and_then(|h| h.target());

        // Branches
        let mut branches: Vec<BranchInfo> = Vec::new();
        let mut branch_map: HashMap<Oid, Vec<BranchInfo>> = HashMap::new();

        // Check if HEAD is detached to set is_head for branches?
        let head_ref_name = self.repo.head().ok().and_then(|h| h.name().map(|s| s.to_string()));
        // List references
        for reference in self.repo.references()? {
            let reference = reference?;
            let name = reference.name().unwrap_or("").to_string();
            if !name.starts_with("refs/heads/") && !name.starts_with("refs/remotes/") {
                continue;
            }
            let is_remote = name.starts_with("refs/remotes/");
            let oid = match reference.peel_to_commit() {
                Ok(c) => c.id(),
                Err(_) => continue,
            };
            let short_name = if is_remote {
                name.trim_start_matches("refs/remotes/").to_string()
            } else {
                name.trim_start_matches("refs/heads/").to_string()
            };
            let is_head = if let Some(ref head_name) = head_ref_name {
                &name == head_name
            } else {
                false
            };
            let b = BranchInfo {
                name: short_name,
                full_ref: name.clone(),
                is_remote,
                is_head,
                oid,
            };
            branch_map.entry(oid).or_default().push(b.clone());
            branches.push(b);
        }

        // Commits via revwalk
        let mut revwalk = self.repo.revwalk()?;
        revwalk.set_sorting(Sort::TIME | Sort::TOPOLOGICAL)?;
        // push all branches
        for branch in &branches {
            let _ = revwalk.push(branch.oid);
        }
        // Also push HEAD if exists
        if let Some(oid) = self.head_oid {
            let _ = revwalk.push(oid);
        }

        let mut commits: Vec<CommitInfo> = Vec::new();
        let mut seen: HashSet<Oid> = HashSet::new();
        for oid_result in revwalk {
            let oid = oid_result?;
            if seen.contains(&oid) { continue; }
            seen.insert(oid);
            if commits.len() >= 500 { break; }
            let commit = match self.repo.find_commit(oid) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let message = commit.message().unwrap_or("").to_string();
            let full_message = message.clone();
            let first_line = message.lines().next().unwrap_or("").to_string();
            let author = commit.author();
            let author_name = author.name().unwrap_or("").to_string();
            let author_email = author.email().unwrap_or("").to_string();
            let author_time = author.when();
            let committer = commit.committer();
            let committer_time = committer.when();
            // Convert to Local DateTime
            let author_date = chrono::DateTime::from_timestamp(author_time.seconds(), 0).unwrap_or_else(|| chrono::DateTime::from_timestamp(0,0).unwrap()).with_timezone(&Local);
            let committer_date = chrono::DateTime::from_timestamp(committer_time.seconds(), 0).unwrap_or_else(|| chrono::DateTime::from_timestamp(0,0).unwrap()).with_timezone(&Local);
            let parents: Vec<Oid> = commit.parents().map(|p| p.id()).collect();
            let branches_here = branch_map.get(&oid).cloned().unwrap_or_default();
            commits.push(CommitInfo {
                oid,
                short: format!("{:.7}", oid.to_string()),
                message: first_line,
                full_message,
                author_name,
                author_email,
                author_date,
                committer_date,
                parents,
                branches: branches_here,
            });
        }

        // If no commits, keep empty

        // Handle uncommitted changes: check repo status
        let mut has_uncommitted = false;
        let mut uncommitted_count = 0;
        {
            let mut opts = StatusOptions::new();
            opts.include_untracked(false).include_ignored(false);
            if let Ok(statuses) = self.repo.statuses(Some(&mut opts)) {
                for entry in statuses.iter() {
                    let s = entry.status();
                    if s.is_wt_modified() || s.is_wt_deleted() || s.is_wt_renamed() || s.is_wt_typechange() || s.is_index_modified() || s.is_index_deleted() || s.is_index_renamed() || s.is_index_typechange() || s.is_index_new() {
                        has_uncommitted = true;
                        uncommitted_count += 1;
                    }
                }
            }
        }

        // Build graph
        let graph_rows = build_graph(&commits, has_uncommitted);

        // Build commit_to_graph_idx mapping
        let mut commit_to_graph_idx = HashMap::new();
        for (idx, row) in graph_rows.iter().enumerate() {
            if let GraphRowKind::Commit(c_idx) = row.kind {
                let oid = commits[c_idx].oid;
                commit_to_graph_idx.insert(oid, idx);
            }
        }

        // If had uncommitted, we inserted a pseudo row at top? Our build_graph will include uncommitted as first commit row with no oid? Let's handle specially: We'll insert a dummy commit at index 0 for uncommitted changes if present, and graph will handle.

        self.commits = commits;
        self.graph_rows = graph_rows;
        self.commit_to_graph_idx = commit_to_graph_idx;

        // Adjust selected index if out of bounds
        if self.commits.is_empty() {
            self.selected_commit_idx = 0;
        } else if self.selected_commit_idx >= self.commits.len() {
            self.selected_commit_idx = self.commits.len() -1;
        }

        // Ensure branch selection per commit
        for commit in &self.commits {
            if !self.selected_branch_per_commit.contains_key(&commit.oid) {
                self.selected_branch_per_commit.insert(commit.oid, 0);
            }
        }

        // Update changed files for selected
        self.update_changed_files()?;

        // Update search results to all branches
        self.search_results = branches.clone();

        Ok(())
    }

    fn update_changed_files(&mut self) -> anyhow::Result<()> {
        if self.commits.is_empty() {
            self.changed_files.clear();
            self.changed_stats = (0,0,0);
            return Ok(());
        }
        let commit = &self.commits[self.selected_commit_idx];
        let (files, stats) = get_changed_files(&self.repo, commit.oid, &commit.parents)?;
        self.changed_files = files;
        self.changed_stats = stats;
        Ok(())
    }

    fn get_selected_branch(&self) -> Option<BranchInfo> {
        if self.commits.is_empty() { return None; }
        let commit = &self.commits[self.selected_commit_idx];
        if commit.branches.is_empty() { return None; }
        let idx = self.selected_branch_per_commit.get(&commit.oid).cloned().unwrap_or(0);
        if idx < commit.branches.len() {
            Some(commit.branches[idx].clone())
        } else {
            commit.branches.first().cloned()
        }
    }

    fn move_down(&mut self) {
        if self.commits.is_empty() { return; }
        if self.selected_commit_idx + 1 < self.commits.len() {
            self.selected_commit_idx += 1;
            if let Err(e) = self.update_changed_files() {
                self.status_msg = Some((format!("Failed to load diff: {}", e), Instant::now(), true));
            }
        }
    }
    fn move_up(&mut self) {
        if self.commits.is_empty() { return; }
        if self.selected_commit_idx > 0 {
            self.selected_commit_idx -=1;
            if let Err(e) = self.update_changed_files() {
                self.status_msg = Some((format!("Failed to load diff: {}", e), Instant::now(), true));
            }
        }
    }
    fn page_down(&mut self) {
        if self.commits.is_empty() { return; }
        let step = 10;
        self.selected_commit_idx = (self.selected_commit_idx + step).min(self.commits.len()-1);
        let _ = self.update_changed_files();
    }
    fn page_up(&mut self) {
        if self.commits.is_empty() { return; }
        let step = 10;
        if self.selected_commit_idx >= step {
            self.selected_commit_idx -= step;
        } else {
            self.selected_commit_idx = 0;
        }
        let _ = self.update_changed_files();
    }
    fn go_top(&mut self) {
        self.selected_commit_idx = 0;
        let _ = self.update_changed_files();
    }
    fn go_bottom(&mut self) {
        if !self.commits.is_empty() {
            self.selected_commit_idx = self.commits.len()-1;
            let _ = self.update_changed_files();
        }
    }
    fn jump_to_head(&mut self) {
        if let Some(head_oid) = self.head_oid {
            if let Some(idx) = self.commits.iter().position(|c| c.oid == head_oid) {
                self.selected_commit_idx = idx;
                let _ = self.update_changed_files();
            }
        }
    }
    fn next_branch_commit(&mut self) {
        if self.commits.is_empty() { return; }
        let start = self.selected_commit_idx +1;
        for i in start..self.commits.len() {
            if !self.commits[i].branches.is_empty() {
                self.selected_commit_idx = i;
                let _ = self.update_changed_files();
                return;
            }
        }
    }
    fn prev_branch_commit(&mut self) {
        if self.commits.is_empty() { return; }
        if self.selected_commit_idx ==0 { return; }
        for i in (0..self.selected_commit_idx).rev() {
            if !self.commits[i].branches.is_empty() {
                self.selected_commit_idx = i;
                let _ = self.update_changed_files();
                return;
            }
        }
    }
    fn select_left_branch(&mut self) {
        if self.commits.is_empty() { return; }
        let oid = self.commits[self.selected_commit_idx].oid;
        if let Some(idx) = self.selected_branch_per_commit.get_mut(&oid) {
            if *idx > 0 {
                *idx -=1;
            }
        }
    }
    fn select_right_branch(&mut self) {
        if self.commits.is_empty() { return; }
        let oid = self.commits[self.selected_commit_idx].oid;
        let branch_count = self.commits[self.selected_commit_idx].branches.len();
        if branch_count ==0 { return; }
        if let Some(idx) = self.selected_branch_per_commit.get_mut(&oid) {
            if *idx +1 < branch_count {
                *idx +=1;
            }
        }
    }

    fn set_status(&mut self, msg: String, is_error: bool) {
        self.status_msg = Some((msg, Instant::now(), is_error));
    }

    fn checkout_selected(&mut self) {
        if self.commits.is_empty() { return; }
        let commit = self.commits[self.selected_commit_idx].clone();
        let selected_branch = self.get_selected_branch();

        // If there's a branch selected, checkout that branch
        // Otherwise checkout commit detached
        let repo_path = self.repo_path.clone();
        // Use git command for simplicity for some operations?
        // For branch checkout, use git2
        if let Some(branch) = selected_branch {
            if branch.is_remote {
                // Checkout remote branch: create or update local branch
                // Remote branch name like "origin/main" -> local name "main" (strip remote prefix)
                // Original behavior: checkout origin/xxx creates/updates local branch and sets upstream only when creating.
                // Let's parse: full_ref is refs/remotes/origin/xxx -> local name xxx (maybe without origin/ prefix)
                // For origin/branch, local name is branch without origin/
                // If remote name is "origin/remoteTest", local would be "remoteTest"
                let local_name = if branch.name.starts_with("origin/") {
                    branch.name.trim_start_matches("origin/").to_string()
                } else {
                    branch.name.clone()
                };
                // Check if local branch already exists
                let local_ref = format!("refs/heads/{}", local_name);
                let exists = self.repo.find_reference(&local_ref).is_ok();
                // Get commit for remote branch
                let target_commit = match self.repo.find_commit(branch.oid) {
                    Ok(c) => c,
                    Err(e) => {
                        self.set_status(format!("Failed to find commit: {}", e), true);
                        return;
                    }
                };
                if exists {
                    // Update local branch to point to remote commit (force)
                    match self.repo.find_reference(&local_ref) {
                        Ok(mut r) => {
                            // Force update
                            if let Err(e) = r.set_target(branch.oid, "checkout remote branch") {
                                self.set_status(format!("Failed to update branch: {}", e), true);
                                return;
                            }
                        }
                        Err(e) => {
                            self.set_status(format!("Failed to find local branch: {}", e), true);
                            return;
                        }
                    }
                } else {
                    // Create local branch
                    if let Err(e) = self.repo.branch(&local_name, &target_commit, false) {
                        self.set_status(format!("Failed to create branch '{}': {}", local_name, e), true);
                        return;
                    }
                    // Set upstream if origin exists and this is new
                    // Upstream is refs/remotes/origin/<local_name> ? Actually remote branch ref is branch.full_ref
                    // We can set upstream
                    if let Ok(mut branch_ref) = self.repo.find_branch(&local_name, git2::BranchType::Local) {
                        let _ = branch_ref.set_upstream(Some(&branch.name));
                    }
                }
                // Checkout local branch
                let obj = match self.repo.revparse_single(&format!("refs/heads/{}", local_name)) {
                    Ok(o) => o,
                    Err(e) => {
                        self.set_status(format!("Failed to find branch: {}", e), true);
                        return;
                    }
                };
                if let Err(e) = self.repo.checkout_tree(&obj, None) {
                    self.set_status(format!("Checkout failed: {}", e), true);
                    return;
                }
                if let Err(e) = self.repo.set_head(&format!("refs/heads/{}", local_name)) {
                    self.set_status(format!("Failed to set HEAD: {}", e), true);
                    return;
                }
                self.set_status(format!("Checked out branch '{}'", local_name), false);
                let _ = self.refresh();
            } else {
                // Local branch
                let obj = match self.repo.revparse_single(&branch.full_ref) {
                    Ok(o) => o,
                    Err(e) => {
                        self.set_status(format!("Failed to find branch: {}", e), true);
                        return;
                    }
                };
                if let Err(e) = self.repo.checkout_tree(&obj, None) {
                    self.set_status(format!("Checkout failed: {}", e), true);
                    return;
                }
                if let Err(e) = self.repo.set_head(&branch.full_ref) {
                    self.set_status(format!("Failed to set HEAD: {}", e), true);
                    return;
                }
                self.set_status(format!("Checked out branch '{}'", branch.name), false);
                let _ = self.refresh();
            }
        } else {
            // Detached commit checkout
            let obj = match self.repo.find_object(commit.oid, None) {
                Ok(o) => o,
                Err(e) => {
                    self.set_status(format!("Failed to find commit: {}", e), true);
                    return;
                }
            };
            if let Err(e) = self.repo.checkout_tree(&obj, None) {
                self.set_status(format!("Checkout failed: {}", e), true);
                return;
            }
            if let Err(e) = self.repo.set_head_detached(commit.oid) {
                self.set_status(format!("Failed to set HEAD: {}", e), true);
                return;
            }
            self.set_status(format!("Checked out commit {}", commit.short), false);
            let _ = self.refresh();
        }
    }

    fn create_branch(&mut self, name: &str) {
        if name.trim().is_empty() {
            self.set_status("Branch name cannot be empty".to_string(), true);
            return;
        }
        if self.commits.is_empty() { return; }
        let commit = &self.commits[self.selected_commit_idx];
        let target = match self.repo.find_commit(commit.oid) {
            Ok(c) => c,
            Err(e) => {
                self.set_status(format!("Failed to find commit: {}", e), true);
                return;
            }
        };
        match self.repo.branch(name, &target, false) {
            Ok(_) => {
                self.set_status(format!("Created branch '{}'", name), false);
                let _ = self.refresh();
            }
            Err(e) => {
                self.set_status(format!("Failed to create branch '{}': {}", name, e), true);
            }
        }
    }

    fn delete_branch(&mut self, branch: BranchInfo) {
        if branch.is_remote {
            self.set_status("Cannot delete remote branch".to_string(), true);
            return;
        }
        // Cannot delete HEAD
        if branch.is_head {
            self.set_status(format!("Cannot delete branch '{}' checked out at '{}'", branch.name, self.repo_path.display()), true);
            // Actually original message was "Cannot delete branch 'feat2' checked out at '/tmp/keifu_test'" - we mimic
            return;
        }
        // Find branch
        match self.repo.find_branch(&branch.name, git2::BranchType::Local) {
            Ok(mut b) => {
                // Check if it's head? Already
                match b.delete() {
                    Ok(_) => {
                        self.set_status(format!("Deleted branch '{}'", branch.name), false);
                        let _ = self.refresh();
                    }
                    Err(e) => {
                        self.set_status(format!("Failed to delete branch '{}': {}", branch.name, e), true);
                    }
                }
            }
            Err(e) => {
                self.set_status(format!("Failed to find branch '{}': {}", branch.name, e), true);
            }
        }
    }

    fn fetch_origin(&mut self) {
        // Use git command via std::process to fetch (since git2 fetch needs credentials callback complex)
        // Try to run "git fetch origin" in repo path
        let output = std::process::Command::new("git")
            .arg("-C")
            .arg(&self.repo_path)
            .arg("fetch")
            .arg("origin")
            .output();
        match output {
            Ok(out) => {
                if out.status.success() {
                    self.set_status("Fetched from origin".to_string(), false);
                    let _ = self.refresh();
                } else {
                    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
                    let combined = format!("{}{}", stdout, stderr).trim().to_string();
                    self.set_status(format!("git fetch failed: {}", combined), true);
                }
            }
            Err(e) => {
                self.set_status(format!("Failed to run git fetch: {}", e), true);
            }
        }
    }
}

fn build_graph(commits: &[CommitInfo], has_uncommitted: bool) -> Vec<GraphRow> {
    // Simplified graph builder
    let mut active: Vec<Option<Oid>> = Vec::new();
    let mut rows: Vec<GraphRow> = Vec::new();

    // If has_uncommitted, we'll insert a pseudo commit row at top with no lanes? Actually we could treat as commit with empty oid
    // For simplicity, we will handle uncommitted as extra row with kind Commit but index maybe special? We'll just insert a row at beginning representing uncommitted changes
    // To keep commits indexing consistent, we'll not insert into commits vec, but insert graph row that is special.

    for (c_idx, commit) in commits.iter().enumerate() {
        // Find position of this commit in active
        let mut pos = None;
        for (i, oid_opt) in active.iter().enumerate() {
            if let Some(oid) = oid_opt {
                if *oid == commit.oid {
                    pos = Some(i);
                    break;
                }
            }
        }
        let pos = if let Some(p) = pos {
            p
        } else {
            // Find first None
            if let Some(empty) = active.iter().position(|o| o.is_none()) {
                empty
            } else {
                active.len()
            }
        };
        // Ensure active has pos
        if pos >= active.len() {
            active.resize(pos+1, None);
        }
        active[pos] = Some(commit.oid);

        // Snapshot for rendering
        let lanes_snapshot = active.clone();
        let new_lanes_placeholder = active.clone(); // will be updated after

        rows.push(GraphRow {
            kind: GraphRowKind::Commit(c_idx),
            lanes: lanes_snapshot.clone(),
            pos,
            new_lanes: new_lanes_placeholder,
        });

        // Compute new active for next iteration
        let mut new_active = active.clone();
        if commit.parents.is_empty() {
            new_active[pos] = None;
        } else {
            new_active[pos] = Some(commit.parents[0]);
            for extra in commit.parents.iter().skip(1) {
                if new_active.iter().any(|o| o.as_ref() == Some(extra)) {
                    continue;
                }
                if let Some(empty) = new_active.iter().position(|o| o.is_none()) {
                    new_active[empty] = Some(*extra);
                } else {
                    new_active.push(Some(*extra));
                }
            }
        }

        // Deduplicate same oid in multiple lanes: keep first occurrence, set others to None, and emit a merge row for each duplicate
        let mut first_occurrence: HashMap<Oid, usize> = HashMap::new();
        let mut duplicates: Vec<(usize, usize)> = Vec::new(); // (from, to)
        for (i, oid_opt) in new_active.iter().enumerate() {
            if let Some(oid) = oid_opt {
                if let Some(&first_idx) = first_occurrence.get(oid) {
                    duplicates.push((i, first_idx));
                } else {
                    first_occurrence.insert(*oid, i);
                }
            }
        }
        // For each duplicate, create a merge row showing connection from duplicate index to first index
        // We'll generate merge rows in order of duplicate from high to low to avoid overlapping?
        for (from, to) in duplicates.iter() {
            // Create merge row
            let merge_lanes = new_active.clone(); // snapshot before removing duplicate?
            rows.push(GraphRow {
                kind: GraphRowKind::Merge { from: *from, to: *to },
                lanes: merge_lanes,
                pos: *to,
                new_lanes: vec![],
            });
        }
        // Now remove duplicates (set duplicate positions to None)
        for (from, _) in duplicates {
            new_active[from] = None;
        }

        active = new_active;
    }

    rows
}

