}

#[derive(Clone, Debug)]
struct CommitInfo {
    oid: Oid,
    short: String,
    message: String,
    full_message: String,
    author_name: String,
    author_email: String,
    author_date: DateTime<Local>,
    committer_date: DateTime<Local>,
    parents: Vec<Oid>,
    branches: Vec<BranchInfo>,
}

#[derive(Clone, Debug)]
struct ChangedFile {
    status: char,
    path: String,
    additions: usize,
    deletions: usize,
}

#[derive(Clone, Debug)]
enum GraphRowKind {
    Commit(usize),
    Merge { from: usize, to: usize },
}

#[derive(Clone, Debug)]
struct GraphRow {
    kind: GraphRowKind,
    lanes: Vec<Option<Oid>>,
    pos: usize,
    new_lanes: Vec<Option<Oid>>,
}

struct App {
    repo_path: PathBuf,
    repo_name: String,
    current_branch: String,
    head_oid: Option<Oid>,
    commits: Vec<CommitInfo>,
    graph_rows: Vec<GraphRow>,
    commit_to_graph_idx: HashMap<Oid, usize>,
    selected_commit_idx: usize,
    selected_branch_per_commit: HashMap<Oid, usize>,
    graph_scroll: usize,
    changed_files: Vec<ChangedFile>,
    changed_stats: (usize, usize, usize),
    mode: Mode,
    help_visible: bool,
    search_query: String,
    search_results: Vec<BranchInfo>,
    search_selected: usize,
    new_branch_input: String,
    delete_confirm_branch: Option<BranchInfo>,
    status_msg: Option<(String, Instant, bool)>,
    config: AppConfig,
    last_refresh: Instant,
    last_fetch: Instant,
    repo: Repository,
}

#[derive(Clone, Debug, PartialEq)]
enum Mode {
    Normal,
    Search,
    NewBranch,
    DeleteConfirm,
}

impl App {
    fn new(repo: Repository) -> anyhow::Result<Self> {
        let repo_path = repo.path().parent().unwrap_or_else(|| std::path::Path::new(".")).to_path_buf();
        let repo_name = repo_path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "repo".to_string());
        let config = load_config();
        let mut app = App {
            repo_path,
            repo_name,
            current_branch: String::new(),
            head_oid: None,
            commits: Vec::new(),
            graph_rows: Vec::new(),
            commit_to_graph_idx: HashMap::new(),
            selected_commit_idx: 0,
            selected_branch_per_commit: HashMap::new(),
            graph_scroll: 0,
            changed_files: Vec::new(),
            changed_stats: (0,0,0),
            mode: Mode::Normal,
            help_visible: false,
            search_query: String::new(),
            search_results: Vec::new(),
            search_selected: 0,
            new_branch_input: String::new(),
            delete_confirm_branch: None,
            status_msg: None,
            config,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
            repo,
        };
        app.refresh()?;
        Ok(app)
    }

    fn refresh(&mut self) -> anyhow::Result<()> {
        self.repo = Repository::discover(&self.repo_path)?;
        self.current_branch = match self.repo.head() {
            Ok(head) => {
                if head.is_branch() {
                    head.shorthand().unwrap_or("HEAD").to_string()
                } else {
                    "HEAD".to_string()
                }
            }
            Err(_) => "".to_string(),
        };
        self.head_oid = self.repo.head().ok().and_then(|h| h.target());

        let mut branches: Vec<BranchInfo> = Vec::new();
        let mut branch_map: HashMap<Oid, Vec<BranchInfo>> = HashMap::new();

        let head_ref_name = self.repo.head().ok().and_then(|h| h.name().map(|s| s.to_string()));

        for reference in self.repo.references()? {
            let reference = reference?;
            let name = reference.name().unwrap_or("").to_string();
            if !name.starts_with("refs/heads/") && !name.starts_with("refs/remotes/") {
                continue;
            }
            let is_remote = name.starts_with("refs/remotes/");
            let oid = match reference.peel_to_commit() {
                Ok(c) => c.id(),
                Err(_) => continue,
            };
            let short_name = if is_remote {
                name.trim_start_matches("refs/remotes/").to_string()
            } else {
                name.trim_start_matches("refs/heads/").to_string()
            };
            let is_head = if let Some(ref head_name) = head_ref_name {
                &name == head_name
            } else {
                false
            };
            let b = BranchInfo {
                name: short_name,
                full_ref: name.clone(),
                is_remote,
                is_head,
                oid,
            };
            branch_map.entry(oid).or_default().push(b.clone());
            branches.push(b);
        }

        let mut revwalk = self.repo.revwalk()?;
        revwalk.set_sorting(Sort::TIME | Sort::TOPOLOGICAL)?;
        for branch in &branches {
            let _ = revwalk.push(branch.oid);
        }
        if let Some(oid) = self.head_oid {
            let _ = revwalk.push(oid);
        }

        let mut commits: Vec<CommitInfo> = Vec::new();
        let mut seen: HashSet<Oid> = HashSet::new();
        for oid_result in revwalk {
            let oid = oid_result?;
            if seen.contains(&oid) { continue; }
            seen.insert(oid);
            if commits.len() >= 500 { break; }
            let commit = match self.repo.find_commit(oid) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let message = commit.message().unwrap_or("").to_string();
            let full_message = message.clone();
            let first_line = message.lines().next().unwrap_or("").to_string();
            let author = commit.author();
            let author_name = author.name().unwrap_or("").to_string();
            let author_email = author.email().unwrap_or("").to_string();
            let author_time = author.when();
            let committer = commit.committer();
            let committer_time = committer.when();
            let author_date = chrono::DateTime::from_timestamp(author_time.seconds(), 0).unwrap_or_else(|| chrono::DateTime::from_timestamp(0,0).unwrap()).with_timezone(&Local);
            let committer_date = chrono::DateTime::from_timestamp(committer_time.seconds(), 0).unwrap_or_else(|| chrono::DateTime::from_timestamp(0,0).unwrap()).with_timezone(&Local);
            let parents: Vec<Oid> = commit.parents().map(|p| p.id()).collect();
            let branches_here = branch_map.get(&oid).cloned().unwrap_or_default();
            commits.push(CommitInfo {
                oid,
                short: format!("{:.7}", oid.to_string()),
                message: first_line,
                full_message,
                author_name,
                author_email,
                author_date,
                committer_date,
                parents,
                branches: branches_here,
            });
        }

        let mut has_uncommitted = false;
        {
            let mut opts = StatusOptions::new();
            opts.include_untracked(false).include_ignored(false);
            if let Ok(statuses) = self.repo.statuses(Some(&mut opts)) {
                for entry in statuses.iter() {
                    let s = entry.status();
                    if s.is_wt_modified() || s.is_wt_deleted() || s.is_wt_renamed() || s.is_wt_typechange() || s.is_index_modified() || s.is_index_deleted() || s.is_index_renamed() || s.is_index_typechange() || s.is_index_new() {
                        has_uncommitted = true;
                        break;
                    }
                }
            }
        }

        let graph_rows = build_graph_v2(&commits);

        let mut commit_to_graph_idx = HashMap::new();
        for (idx, row) in graph_rows.iter().enumerate() {
            if let GraphRowKind::Commit(c_idx) = row.kind {
                let oid = commits[c_idx].oid;
                commit_to_graph_idx.insert(oid, idx);
            }
        }

        self.commits = commits;
        self.graph_rows = graph_rows;
        self.commit_to_graph_idx = commit_to_graph_idx;

        if self.commits.is_empty() {
            self.selected_commit_idx = 0;
        } else if self.selected_commit_idx >= self.commits.len() {
            self.selected_commit_idx = self.commits.len() -1;
        }

        for commit in &self.commits {
            if !self.selected_branch_per_commit.contains_key(&commit.oid) {
                self.selected_branch_per_commit.insert(commit.oid, 0);
            }
        }

        self.update_changed_files()?;

        self.search_results = branches.clone();

        Ok(())
    }

    fn update_changed_files(&mut self) -> anyhow::Result<()> {
        if self.commits.is_empty() {
            self.changed_files.clear();
            self.changed_stats = (0,0,0);
            return Ok(());
        }
        let commit = &self.commits[self.selected_commit_idx];
        let oid = commit.oid;
        let parents = commit.parents.clone();
        let (files, stats) = get_changed_files(&self.repo, oid, &parents)?;
        self.changed_files = files;
        self.changed_stats = stats;
        Ok(())
    }

    fn get_selected_branch(&self) -> Option<BranchInfo> {
        if self.commits.is_empty() { return None; }
        let commit = &self.commits[self.selected_commit_idx];
        if commit.branches.is_empty() { return None; }
        let idx = self.selected_branch_per_commit.get(&commit.oid).cloned().unwrap_or(0);
        if idx < commit.branches.len() {
            Some(commit.branches[idx].clone())
        } else {
            commit.branches.first().cloned()
        }
    }

    fn move_down(&mut self) {
        if self.commits.is_empty() { return; }
        if self.selected_commit_idx + 1 < self.commits.len() {
            self.selected_commit_idx += 1;
            let _ = self.update_changed_files();
        }
    }
    fn move_up(&mut self) {
        if self.commits.is_empty() { return; }
        if self.selected_commit_idx > 0 {
            self.selected_commit_idx -=1;
            let _ = self.update_changed_files();
        }
    }
    fn page_down(&mut self) {
        if self.commits.is_empty() { return; }
        let step = 10;
        self.selected_commit_idx = (self.selected_commit_idx + step).min(self.commits.len()-1);
        let _ = self.update_changed_files();
    }
    fn page_up(&mut self) {
        if self.commits.is_empty() { return; }
        let step = 10;
        if self.selected_commit_idx >= step {
            self.selected_commit_idx -= step;
        } else {
            self.selected_commit_idx = 0;
        }
        let _ = self.update_changed_files();
    }
    fn go_top(&mut self) {
        self.selected_commit_idx = 0;
        let _ = self.update_changed_files();
    }
    fn go_bottom(&mut self) {
        if !self.commits.is_empty() {
            self.selected_commit_idx = self.commits.len()-1;
            let _ = self.update_changed_files();
        }
    }
    fn jump_to_head(&mut self) {
        if let Some(head_oid) = self.head_oid {
            if let Some(idx) = self.commits.iter().position(|c| c.oid == head_oid) {
                self.selected_commit_idx = idx;
                let _ = self.update_changed_files();
            }
        }
    }
    fn next_branch_commit(&mut self) {
        if self.commits.is_empty() { return; }
        let start = self.selected_commit_idx +1;
        for i in start..self.commits.len() {
            if !self.commits[i].branches.is_empty() {
                self.selected_commit_idx = i;
                let _ = self.update_changed_files();
                return;
            }
        }
    }
    fn prev_branch_commit(&mut self) {
        if self.commits.is_empty() { return; }
        if self.selected_commit_idx ==0 { return; }
        for i in (0..self.selected_commit_idx).rev() {
            if !self.commits[i].branches.is_empty() {
                self.selected_commit_idx = i;
                let _ = self.update_changed_files();
                return;
            }
        }
    }
    fn select_left_branch(&mut self) {
        if self.commits.is_empty() { return; }
        let oid = self.commits[self.selected_commit_idx].oid;
        if let Some(idx) = self.selected_branch_per_commit.get_mut(&oid) {
            if *idx > 0 {
                *idx -=1;
            }
        }
    }
    fn select_right_branch(&mut self) {
        if self.commits.is_empty() { return; }
        let oid = self.commits[self.selected_commit_idx].oid;
        let branch_count = self.commits[self.selected_commit_idx].branches.len();
        if branch_count ==0 { return; }
        if let Some(idx) = self.selected_branch_per_commit.get_mut(&oid) {
            if *idx +1 < branch_count {
                *idx +=1;
            }
        }
    }

    fn set_status(&mut self, msg: String, is_error: bool) {
        self.status_msg = Some((msg, Instant::now(), is_error));
    }

    fn checkout_selected(&mut self) {
        if self.commits.is_empty() { return; }
        let commit_oid = self.commits[self.selected_commit_idx].oid;
        let selected_branch = self.get_selected_branch();

        if let Some(branch) = selected_branch {
            if branch.is_remote {
                let local_name = if branch.name.starts_with("origin/") {
                    branch.name.trim_start_matches("origin/").to_string()
                } else {
                    branch.name.clone()
                };
                let local_ref = format!("refs/heads/{}", local_name);
                let exists = self.repo.find_reference(&local_ref).is_ok();
                let target_oid = branch.oid;

                // To avoid borrow issues, drop any commit objects before mutable ops
                if exists {
                    let res = {
                        let mut r = match self.repo.find_reference(&local_ref) {
                            Ok(r) => r,
                            Err(e) => {
                                self.set_status(format!("Failed to find local branch: {}", e), true);
                                return;
                            }
                        };
                        r.set_target(target_oid, "checkout remote branch")
                    };
                    if let Err(e) = res {
                        self.set_status(format!("Failed to update branch: {}", e), true);
                        return;
                    }
                } else {
                    let target_commit = match self.repo.find_commit(target_oid) {
                        Ok(c) => c,
                        Err(e) => {
                            self.set_status(format!("Failed to find commit: {}", e), true);
                            return;
                        }
                    };
                    let create_res = self.repo.branch(&local_name, &target_commit, false);
                    drop(target_commit);
                    if let Err(e) = create_res {
                        self.set_status(format!("Failed to create branch '{}': {}", local_name, e), true);
                        return;
                    }
                    if let Ok(mut branch_ref) = self.repo.find_branch(&local_name, git2::BranchType::Local) {
                        let _ = branch_ref.set_upstream(Some(&branch.name));
                    }
                }
                let obj = match self.repo.revparse_single(&format!("refs/heads/{}", local_name)) {
                    Ok(o) => o,
                    Err(e) => {
                        self.set_status(format!("Failed to find branch: {}", e), true);
                        return;
                    }
                };
                if let Err(e) = self.repo.checkout_tree(&obj, None) {
                    self.set_status(format!("Checkout failed: {}", e), true);
                    return;
                }
                if let Err(e) = self.repo.set_head(&format!("refs/heads/{}", local_name)) {
                    self.set_status(format!("Failed to set HEAD: {}", e), true);
                    return;
                }
                self.set_status(format!("Checked out branch '{}'", local_name), false);
                let _ = self.refresh();
            } else {
                let full_ref = branch.full_ref.clone();
                let branch_name = branch.name.clone();
                let obj = match self.repo.revparse_single(&full_ref) {
                    Ok(o) => o,
                    Err(e) => {
                        self.set_status(format!("Failed to find branch: {}", e), true);
                        return;
                    }
                };
                if let Err(e) = self.repo.checkout_tree(&obj, None) {
                    self.set_status(format!("Checkout failed: {}", e), true);
                    return;
                }
                if let Err(e) = self.repo.set_head(&full_ref) {
                    self.set_status(format!("Failed to set HEAD: {}", e), true);
                    return;
                }
                self.set_status(format!("Checked out branch '{}'", branch_name), false);
                let _ = self.refresh();
            }
        } else {
            let oid = commit_oid;
            let obj = match self.repo.find_object(oid, None) {
                Ok(o) => o,
                Err(e) => {
                    self.set_status(format!("Failed to find commit: {}", e), true);
                    return;
                }
            };
            let short = format!("{:.7}", oid.to_string());
            if let Err(e) = self.repo.checkout_tree(&obj, None) {
                self.set_status(format!("Checkout failed: {}", e), true);
                return;
            }
            drop(obj);
            if let Err(e) = self.repo.set_head_detached(oid) {
                self.set_status(format!("Failed to set HEAD: {}", e), true);
                return;
            }
            self.set_status(format!("Checked out commit {}", short), false);
            let _ = self.refresh();
        }
    }

    fn create_branch(&mut self, name: &str) {
        if name.trim().is_empty() {
            self.set_status("Branch name cannot be empty".to_string(), true);
            return;
        }
        if self.commits.is_empty() { return; }
        let oid = self.commits[self.selected_commit_idx].oid;
        let target = match self.repo.find_commit(oid) {
            Ok(c) => c,
            Err(e) => {
                self.set_status(format!("Failed to find commit: {}", e), true);
                return;
            }
        };
        let res = self.repo.branch(name, &target, false);
        drop(target);
        match res {
            Ok(_) => {
                self.set_status(format!("Created branch '{}'", name), false);
                let _ = self.refresh();
            }
            Err(e) => {
                self.set_status(format!("Failed to create branch '{}': {}", name, e), true);
            }
        }
    }

    fn delete_branch(&mut self, branch: BranchInfo) {
        if branch.is_remote {
            self.set_status("Cannot delete remote branch".to_string(), true);
            return;
        }
        if branch.is_head {
            self.set_status(format!("Cannot delete branch '{}' checked out at '{}'", branch.name, self.repo_path.display()), true);
            return;
        }
        let name = branch.name.clone();
        match self.repo.find_branch(&name, git2::BranchType::Local) {
            Ok(mut b) => {
                match b.delete() {
                    Ok(_) => {
                        self.set_status(format!("Deleted branch '{}'", name), false);
                        let _ = self.refresh();
                    }
                    Err(e) => {
                        self.set_status(format!("Failed to delete branch '{}': {}", name, e), true);
                    }
                }
            }
            Err(e) => {
                self.set_status(format!("Failed to find branch '{}': {}", name, e), true);
            }
        }
    }

    fn fetch_origin(&mut self) {
        let output = std::process::Command::new("git")
            .arg("-C")
            .arg(&self.repo_path)
            .arg("fetch")
            .arg("origin")
            .output();
        match output {
            Ok(out) => {
                if out.status.success() {
                    self.set_status("Fetched from origin".to_string(), false);
                    let _ = self.refresh();
                } else {
                    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
                    let stdout = String::from_utf8_lossy(&out.stdout).to_string();
                    let combined = format!("{}{}", stdout, stderr).trim().to_string();
                    self.set_status(format!("git fetch failed: {}", combined), true);
                }
            }
            Err(e) => {
                self.set_status(format!("Failed to run git fetch: {}", e), true);
            }
        }
    }
}

fn build_graph_v2(commits: &[CommitInfo]) -> Vec<GraphRow> {
    let mut active: Vec<Option<Oid>> = Vec::new();
    let mut rows: Vec<GraphRow> = Vec::new();

    for (c_idx, commit) in commits.iter().enumerate() {
        let mut pos = None;
        for (i, oid_opt) in active.iter().enumerate() {
            if let Some(oid) = oid_opt {
                if *oid == commit.oid {
                    pos = Some(i);
                    break;
                }
            }
        }
        let pos = if let Some(p) = pos {
            p
        } else {
            if let Some(empty) = active.iter().position(|o| o.is_none()) {
                empty
            } else {
                active.len()
            }
        };
        if pos >= active.len() {
            active.resize(pos+1, None);
        }
        active[pos] = Some(commit.oid);
        let snapshot_before = active.clone();

        let mut new_active = active.clone();
        if commit.parents.is_empty() {
            new_active[pos] = None;
        } else {
            new_active[pos] = Some(commit.parents[0]);
            for extra in commit.parents.iter().skip(1) {
                if new_active.iter().any(|o| o.as_ref() == Some(extra)) {
                    continue;
                }
                if let Some(empty) = new_active.iter().position(|o| o.is_none()) {
                    new_active[empty] = Some(*extra);
                } else {
                    new_active.push(Some(*extra));
                }
            }
        }

        rows.push(GraphRow {
            kind: GraphRowKind::Commit(c_idx),
            lanes: snapshot_before.clone(),
            pos,
            new_lanes: new_active.clone(),
        });

        let mut first_occ: HashMap<Oid, usize> = HashMap::new();
        let mut dups = Vec::new();
        for (i, oid_opt) in new_active.iter().enumerate() {
            if let Some(oid) = oid_opt {
                if let Some(&first) = first_occ.get(oid) {
                    dups.push((i, first));
                } else {
                    first_occ.insert(*oid, i);
                }
            }
        }
        for (from, to) in dups.clone() {
            rows.push(GraphRow {
                kind: GraphRowKind::Merge { from, to },
                lanes: new_active.clone(),
                pos: to,
                new_lanes: vec![],
            });
        }
        for (from, _) in dups {
            new_active[from] = None;
        }

        active = new_active;
    }

    rows
}

fn render_graph_line_v2(row: &GraphRow, is_selected: bool, _commits: &[CommitInfo]) -> String {
    match &row.kind {
        GraphRowKind::Commit(_) => {
            let lanes = &row.lanes;
            let new_lanes = &row.new_lanes;
            let pos = row.pos;
            let max_len = lanes.len().max(new_lanes.len());
            let extra_positions: Vec<usize> = new_lanes.iter().enumerate().filter_map(|(i, oid)| {
                if i == pos { return None; }
                if let Some(oid) = oid {
                    if !lanes.iter().any(|o| o.as_ref() == Some(oid)) {
                        Some(i)
                    } else { None }
                } else { None }
            }).collect();
            let max_extra_pos = extra_positions.iter().max().cloned();

            let mut chars: Vec<char> = Vec::new();
            for i in 0..max_len {
                let lane_oid = if i < lanes.len() { lanes[i] } else { None };
                let is_pos = i == pos;
                let ch_first = if is_pos {
                    if is_selected { '◉' } else { '●' }
                } else if lane_oid.is_some() {
                    if let Some(max_e) = max_extra_pos {
                        if i > pos && i <= max_e {
                            '┼'
                        } else {
                            '│'
                        }
                    } else {
                        '│'
                    }
                } else {
                    if let Some(max_e) = max_extra_pos {
                        if i > pos && i <= max_e {
                            '─'
                        } else {
                            ' '
                        }
                    } else {
                        ' '
                    }
                };
                chars.push(ch_first);
                if i+1 < max_len {
                    if let Some(max_e) = max_extra_pos {
                        if i >= pos && i < max_e {
                            chars.push('─');
                        } else {
                            chars.push(' ');
                        }
                    } else {
                        if i == pos {
                            let has_right = lanes.iter().skip(i+1).any(|o| o.is_some());
                            if has_right {
                                chars.push('─');
                            } else {
                                chars.push(' ');
                            }
                        } else {
                            chars.push(' ');
                        }
                    }
                }
            }
            if let Some(max_e) = max_extra_pos {
                let idx = max_e * 2;
                if idx < chars.len() {
                    let was_empty = if max_e < lanes.len() { lanes[max_e].is_none() } else { true };
                    if was_empty {
                        chars[idx] = '╮';
                    }
                }
            }
            chars.into_iter().collect()
        }
        GraphRowKind::Merge { from, to } => {
            let lanes = &row.lanes;
            let max_len = lanes.len();
            let mut chars: Vec<char> = Vec::new();
            let start = (*from).min(*to);
            let end = (*from).max(*to);
            for i in 0..max_len {
                let lane_oid = if i < lanes.len() { lanes[i] } else { None };
                let ch = if i == *from && i == *to {
                    '│'
                } else if i == *from {
                    if from < to { '├' } else { '╰' }
                } else if i == *to {
                    if from < to { '╯' } else { '┤' }
                } else if i > start && i < end {
                    '─'
                } else if lane_oid.is_some() {
                    '│'
                } else {
                    ' '
                };
                chars.push(ch);
                if i+1 < max_len {
                    if i >= start && i < end {
                        chars.push('─');
                    } else {
                        chars.push(' ');
                    }
                }
            }
            chars.into_iter().collect()
        }
    }
}

fn get_changed_files(repo: &Repository, oid: Oid, parents: &[Oid]) -> anyhow::Result<(Vec<ChangedFile>, (usize, usize, usize))> {
    let commit = repo.find_commit(oid)?;
    let tree = commit.tree()?;
    let parent_tree = if parents.is_empty() {
        None
    } else {
        match repo.find_commit(parents[0]) {
            Ok(p) => Some(p.tree()?),
            Err(_) => None,
        }
    };

    let diff = match parent_tree {
        Some(pt) => repo.diff_tree_to_tree(Some(&pt), Some(&tree), None)?,
        None => repo.diff_tree_to_tree(None, Some(&tree), None)?,
    };

    let mut files: Vec<ChangedFile> = Vec::new();

    let mut deltas = Vec::new();
    diff.foreach(&mut |delta, _| {
        deltas.push((delta.status(), delta.new_file().path().map(|p| p.to_path_buf()), delta.old_file().path().map(|p| p.to_path_buf())));
        true
    }, None, None, None)?;

    for (status, new_path, old_path) in deltas {
        let path = new_path.or(old_path).map(|p| p.to_string_lossy().to_string()).unwrap_or_else(|| "".to_string());
        if path.is_empty() { continue; }
        let status_char = match status {
            git2::Delta::Added => 'A',
            git2::Delta::Deleted => 'D',
            git2::Delta::Modified => 'M',
            git2::Delta::Renamed => 'R',
            git2::Delta::Copied => 'C',
            _ => 'M',
        };
        files.push(ChangedFile {
            status: status_char,
            path,
            additions: 0,
            deletions: 0,
        });
        if files.len() >= 50 {
            break;
        }
    }

    let mut total_add = 0usize;
    let mut total_del = 0usize;
    let mut files_changed = files.len();
    if let Ok(stats) = diff.stats() {
        total_add = stats.insertions();
        total_del = stats.deletions();
        files_changed = stats.files_changed();
    }

    Ok((files, (files_changed, total_add, total_del)))
}

fn fuzzy_match(query: &str, target: &str) -> bool {
    let query = query.to_lowercase();
    let target = target.to_lowercase();
    let q_chars: Vec<char> = query.chars().collect();
    let t_chars: Vec<char> = target.chars().collect();
    let mut ti = 0;
    for qc in q_chars {
        let mut found = false;
        while ti < t_chars.len() {
            if t_chars[ti] == qc {
                found = true;
                ti+=1;
                break;
            }
            ti+=1;
        }
        if !found {
            return false;
        }
    }
    true
}

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 {
        match args[1].as_str() {
            "-h" | "--help" => {
                println!("A TUI tool to visualize Git commit graphs with branch genealogy\n\nUsage: executable\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version");
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("keifu 0.2.3");
                std::process::exit(0);
            }
            _ => {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable\n\nFor more information, try '--help'.", args[1]);
                std::process::exit(2);
            }
        }
    }

    if !crossterm::tty::IsTty::is_tty(&std::io::stdout()) {
        eprintln!("Error: No such device or address (os error 6)");
        std::process::exit(1);
    }

    let repo = match Repository::discover(".") {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: Git repository not found. Please run inside a Git repository.\n\nCaused by:\n    {}", e);
            std::process::exit(1);
        }
    };

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend)?;

    let app = App::new(repo)?;
    let res = run_app(&mut terminal, app);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Error: {}", err);
        std::process::exit(1);
    }

    Ok(())
}

fn run_app<B: ratatui::backend::Backend>(terminal: &mut ratatui::Terminal<B>, mut app: App) -> std::io::Result<()> where B::Error: Send + Sync + 'static {
    loop {
        let _ = terminal.draw(|f| ui(f, &mut app));

        if app.config.auto_refresh {
            if app.last_refresh.elapsed() >= Duration::from_secs(app.config.refresh_interval) {
                let _ = app.refresh();
                app.last_refresh = Instant::now();
            }
        }
        if app.config.auto_fetch {
            if app.last_fetch.elapsed() >= Duration::from_secs(app.config.fetch_interval) {
                app.fetch_origin();
                app.last_fetch = Instant::now();
            }
        }

        if let Some((_, instant, _)) = &app.status_msg {
            if instant.elapsed() > Duration::from_secs(5) {
                app.status_msg = None;
            }
        }

        if event::poll(Duration::from_millis(200))? {
            if let Event::Key(key) = event::read()? {
                match app.mode {
                    Mode::Normal => {
                        if app.help_visible {
                            match key.code {
                                KeyCode::Char('?') | KeyCode::Esc | KeyCode::Char('q') => {
                                    app.help_visible = false;
                                }
                                _ => {}
                            }
                            continue;
                        }
                        match key.code {
                            KeyCode::Char('q') | KeyCode::Esc => {
                                return Ok(());
                            }
                            KeyCode::Char('j') | KeyCode::Down => {
                                app.move_down();
                            }
                            KeyCode::Char('k') | KeyCode::Up => {
                                app.move_up();
                            }
                            KeyCode::Char('g') | KeyCode::Home => {
                                app.go_top();
                            }
                            KeyCode::Char('G') | KeyCode::End => {
                                app.go_bottom();
                            }
                            KeyCode::Char('@') => {
                                app.jump_to_head();
                            }
                            KeyCode::Char(']') | KeyCode::Tab => {
                                app.next_branch_commit();
                            }
                            KeyCode::Char('[') => {
                                app.prev_branch_commit();
                            }
                            KeyCode::BackTab => {
                                app.prev_branch_commit();
                            }
                            KeyCode::Char('h') | KeyCode::Left => {
                                app.select_left_branch();
                            }
                            KeyCode::Char('l') | KeyCode::Right => {
                                app.select_right_branch();
                            }
                            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.page_down();
                            }
                            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.page_up();
                            }
                            KeyCode::Char('R') => {
                                let _ = app.refresh();
                                app.set_status("Refreshed".to_string(), false);
                            }
                            KeyCode::Char('?') => {
                                app.help_visible = true;
                            }
                            KeyCode::Char('/') => {
                                app.mode = Mode::Search;
                                app.search_query.clear();
                                app.search_selected = 0;
                            }
                            KeyCode::Char('b') => {
                                app.mode = Mode::NewBranch;
                                app.new_branch_input.clear();
                            }
                            KeyCode::Char('d') => {
                                if let Some(branch) = app.get_selected_branch() {
                                    if branch.is_remote {
                                        app.set_status("Cannot delete remote branch".to_string(), true);
                                    } else {
                                        app.mode = Mode::DeleteConfirm;
                                        app.delete_confirm_branch = Some(branch);
                                    }
                                }
                            }
                            KeyCode::Char('f') => {
                                app.fetch_origin();
                            }
                            KeyCode::Enter => {
                                app.checkout_selected();
                            }
                            _ => {}
                        }
                    }
                    Mode::Search => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = Mode::Normal;
                                app.search_query.clear();
                            }
                            KeyCode::Enter => {
                                if let Some(branch) = app.search_results.get(app.search_selected).cloned() {
                                    if let Some(idx) = app.commits.iter().position(|c| c.oid == branch.oid) {
                                        app.selected_commit_idx = idx;
                                        let _ = app.update_changed_files();
                                        if let Some(pos) = app.commits[idx].branches.iter().position(|b| b.name == branch.name && b.is_remote == branch.is_remote) {
                                            app.selected_branch_per_commit.insert(branch.oid, pos);
                                        }
                                    }
                                }
                                app.mode = Mode::Normal;
                            }
                            KeyCode::Up => {
                                if app.search_selected > 0 {
                                    app.search_selected -=1;
                                }
                            }
                            KeyCode::Down => {
                                if app.search_selected +1 < app.search_results.len() {
                                    app.search_selected +=1;
                                }
                            }
                            KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if app.search_selected >0 { app.search_selected-=1; }
                            }
                            KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if app.search_selected+1 < app.search_results.len() { app.search_selected+=1; }
                            }
                            KeyCode::Backspace => {
                                if app.search_query.is_empty() {
                                    app.mode = Mode::Normal;
                                } else {
                                    app.search_query.pop();
                                    let query = app.search_query.clone();
                                    let mut all_branches: Vec<BranchInfo> = Vec::new();
                                    let mut seen = HashSet::new();
                                    for c in &app.commits {
                                        for b in &c.branches {
                                            if seen.insert((b.name.clone(), b.is_remote)) {
                                                all_branches.push(b.clone());
                                            }
                                        }
                                    }
                                    if query.is_empty() {
                                        app.search_results = all_branches;
                                    } else {
                                        app.search_results = all_branches.into_iter().filter(|b| fuzzy_match(&query, &b.name)).collect();
                                    }
                                    app.search_selected = 0;
                                }
                            }
                            KeyCode::Char(c) => {
                                app.search_query.push(c);
                                let query = app.search_query.clone();
                                let mut all_branches: Vec<BranchInfo> = Vec::new();
                                let mut seen = HashSet::new();
                                for commit in &app.commits {
                                    for b in &commit.branches {
                                        if seen.insert((b.name.clone(), b.is_remote)) {
                                            all_branches.push(b.clone());
                                        }
                                    }
                                }
                                if query.is_empty() {
                                    app.search_results = all_branches;
                                } else {
                                    app.search_results = all_branches.into_iter().filter(|b| fuzzy_match(&query, &b.name)).collect();
                                }
                                app.search_selected = 0;
                            }
                            _ => {}
                        }
                    }
                    Mode::NewBranch => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = Mode::Normal;
                            }
                            KeyCode::Enter => {
                                let name = app.new_branch_input.clone();
                                app.mode = Mode::Normal;
                                app.create_branch(&name);
                            }
                            KeyCode::Backspace => {
                                app.new_branch_input.pop();
                            }
                            KeyCode::Char(c) => {
                                app.new_branch_input.push(c);
                            }
                            _ => {}
                        }
                    }
                    Mode::DeleteConfirm => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = Mode::Normal;
                                app.delete_confirm_branch = None;
                            }
                            KeyCode::Enter => {
                                if let Some(branch) = app.delete_confirm_branch.take() {
                                    app.delete_branch(branch);
                                }
                                app.mode = Mode::Normal;
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let size = f.area();

    let vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(12), Constraint::Length(1)])
        .split(size);

    let commits_area = vertical[0];
    let bottom_area = vertical[1];
    let status_area = vertical[2];

    let bottom_horizontal = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(bottom_area);

    let commit_detail_area = bottom_horizontal[0];
    let changed_files_area = bottom_horizontal[1];

    let commits_block = Block::default()
        .title(" Commits ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));

    let inner_commits = commits_block.inner(commits_area);
    f.render_widget(commits_block, commits_area);

    let selected_graph_idx = if app.commits.is_empty() {
        0
    } else {
        let oid = app.commits[app.selected_commit_idx].oid;
        *app.commit_to_graph_idx.get(&oid).unwrap_or(&0)
    };

    let visible_height = inner_commits.height as usize;
    if selected_graph_idx < app.graph_scroll {
        app.graph_scroll = selected_graph_idx;
    } else if selected_graph_idx >= app.graph_scroll + visible_height {
        app.graph_scroll = selected_graph_idx - visible_height + 1;
    }

    let mut lines_to_render: Vec<Line> = Vec::new();
    let colors_palette = vec![Color::Blue, Color::Green, Color::Magenta, Color::Cyan, Color::Yellow, Color::LightRed, Color::LightGreen, Color::LightBlue];

    for graph_row in app.graph_rows.iter().skip(app.graph_scroll).take(visible_height) {
        let is_selected_commit = match &graph_row.kind {
            GraphRowKind::Commit(c_idx) => *c_idx == app.selected_commit_idx,
            _ => false,
        };

        let graph_str = render_graph_line_v2(graph_row, is_selected_commit, &app.commits);

        let line = if let GraphRowKind::Commit(c_idx) = &graph_row.kind {
            let commit = &app.commits[*c_idx];
            let branch_label_str = if commit.branches.is_empty() {
                "".to_string()
            } else {
                let sel_branch_idx = app.selected_branch_per_commit.get(&commit.oid).cloned().unwrap_or(0);
                let sel_branch = &commit.branches[sel_branch_idx.min(commit.branches.len()-1)];
                let extra_count = commit.branches.len() -1;
                if commit.branches.len() > 1 {
                    let sel_base = if sel_branch.is_remote {
                        if sel_branch.name.starts_with("origin/") { sel_branch.name.trim_start_matches("origin/").to_string() } else { sel_branch.name.clone() }
                    } else { sel_branch.name.clone() };
                    let mut counterpart_exists = false;
                    for b in &commit.branches {
                        if b.is_remote != sel_branch.is_remote {
                            let b_base = if b.is_remote {
                                if b.name.starts_with("origin/") { b.name.trim_start_matches("origin/").to_string() } else { b.name.clone() }
                            } else { b.name.clone() };
                            if b_base == sel_base {
                                counterpart_exists = true;
                                break;
                            }
                        }
                    }
                    if counterpart_exists {
                        if extra_count ==1 {
                            format!("[{} ↔ origin]", sel_base)
                        } else {
                            format!("[{} ↔ origin] +{}", sel_base, extra_count-1)
                        }
                    } else {
                        format!("[{}] +{}", sel_branch.name, extra_count)
                    }
                } else {
                    format!("[{}]", sel_branch.name)
                }
            };

            let date_str = commit.committer_date.format("%Y-%m-%d").to_string();
            let author = commit.author_name.clone();
            let hash = commit.short.clone();

            let graph_width = graph_str.chars().count() + 2;
            let inner_width = inner_commits.width as usize;
            let remaining = inner_width.saturating_sub(graph_width);

            let mut info_part = String::new();
            if !branch_label_str.is_empty() {
                info_part.push_str(&branch_label_str);
                info_part.push(' ');
            }
            info_part.push_str(&commit.message);

            let mut right_part = String::new();
            if inner_width >= 100 {
                right_part = format!(" {}  {}  {}", date_str, author, hash);
            } else if inner_width >= 80 {
                right_part = format!(" {}  {}", date_str, author);
            }

            let right_len = right_part.chars().count();
            let max_info_len = remaining.saturating_sub(right_len).saturating_sub(2);
            let truncated_info = if info_part.chars().count() > max_info_len {
                let mut s: String = info_part.chars().take(max_info_len.saturating_sub(1)).collect();
                if max_info_len>0 { s.push('…'); }
                s
            } else { info_part };

            let mut spans = Vec::new();
            for (i, ch) in graph_str.chars().enumerate() {
                let color = colors_palette[i % colors_palette.len()];
                spans.push(Span::styled(ch.to_string(), Style::default().fg(color)));
            }
            spans.push(Span::raw("  "));
            if !branch_label_str.is_empty() {
                spans.push(Span::styled(branch_label_str.clone(), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)));
                spans.push(Span::raw(" "));
            }
            spans.push(Span::raw(commit.message.clone()));

            let info_len = truncated_info.chars().count() + 2 + graph_width;
            let padding = inner_width.saturating_sub(info_len).saturating_sub(right_len);
            spans.push(Span::raw(" ".repeat(padding)));
            if !right_part.is_empty() {
                spans.push(Span::styled(right_part, Style::default().fg(Color::DarkGray)));
            }

            let mut line = Line::from(spans);
            if is_selected_commit {
                line = line.style(Style::default().bg(Color::DarkGray).add_modifier(Modifier::BOLD));
            }
            line
        } else {
            let mut spans = Vec::new();
            for (i, ch) in graph_str.chars().enumerate() {
                let color = colors_palette[i % colors_palette.len()];
                spans.push(Span::styled(ch.to_string(), Style::default().fg(color)));
            }
            Line::from(spans)
        };
        lines_to_render.push(line);
    }

    let paragraph = Paragraph::new(lines_to_render);
    f.render_widget(paragraph, inner_commits);

    let detail_block = Block::default()
        .title(" Commit Detail ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));
    let inner_detail = detail_block.inner(commit_detail_area);
    f.render_widget(detail_block, commit_detail_area);

    if app.commits.is_empty() {
        let p = Paragraph::new("Select a commit");
        f.render_widget(p, inner_detail);
    } else {
        let commit = &app.commits[app.selected_commit_idx];
        let parent_str = if commit.parents.is_empty() {
            "".to_string()
        } else {
            commit.parents.iter().map(|oid| format!("{:.7}", oid.to_string())).collect::<Vec<_>>().join(", ")
        };
        let text_lines = vec![
            Line::from(vec![Span::styled("Commit: ", Style::default().add_modifier(Modifier::BOLD)), Span::styled(commit.oid.to_string(), Style::default().fg(Color::Yellow))]),
            Line::from(vec![Span::styled("Author: ", Style::default().add_modifier(Modifier::BOLD)), Span::styled(format!("{} <{}>", commit.author_name, commit.author_email), Style::default().fg(Color::Blue))]),
            Line::from(vec![Span::styled("Date:   ", Style::default().add_modifier(Modifier::BOLD)), Span::raw(commit.author_date.format("%Y-%m-%d %H:%M:%S").to_string())]),
            Line::from(vec![Span::styled("Parent: ", Style::default().add_modifier(Modifier::BOLD)), Span::raw(parent_str)]),
            Line::from(""),
            Line::from(commit.full_message.clone()),
        ];
        let p = Paragraph::new(text_lines);
        f.render_widget(p, inner_detail);
    }

    let changed_block = Block::default()
        .title(" Changed Files ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::DarkGray));
    let inner_changed = changed_block.inner(changed_files_area);
    f.render_widget(changed_block, changed_files_area);

    let (files_changed, adds, dels) = app.changed_stats;
    let header = format!("{} files changed  +{} -{}", files_changed, adds, dels);
    let mut cf_lines = vec![
        Line::from(vec![Span::styled(header, Style::default().add_modifier(Modifier::BOLD))]),
        Line::from(""),
    ];
    for file in &app.changed_files {
        let line = format!(" {} {} +{} -{}", file.status, file.path, file.additions, file.deletions);
        cf_lines.push(Line::from(line));
        if cf_lines.len() > 50 { break; }
    }
    let p = Paragraph::new(cf_lines);
    f.render_widget(p, inner_changed);

    let repo_name = app.repo_name.clone();
    let branch_name = app.current_branch.clone();
    let mut status_spans = Vec::new();
    status_spans.push(Span::styled(format!(" {} ", repo_name), Style::default().bg(Color::Magenta).fg(Color::Black).add_modifier(Modifier::BOLD)));
    status_spans.push(Span::raw(" "));
    status_spans.push(Span::styled(format!(" {} ", branch_name), Style::default().bg(Color::Green).fg(Color::Black)));
    status_spans.push(Span::raw(" "));

    if let Some((msg, _, is_err)) = &app.status_msg {
        let style = if *is_err { Style::default().bg(Color::Red).fg(Color::White) } else { Style::default().bg(Color::Blue).fg(Color::White) };
        status_spans.push(Span::styled(format!(" {} ", msg), style));
        status_spans.push(Span::raw(" "));
        status_spans.push(Span::styled(if *is_err { " ERROR" } else { " INFO" }, Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)));
    } else {
        if app.help_visible {
            status_spans.push(Span::styled(" Esc/q close help ", Style::default()));
            status_spans.push(Span::raw(" ".repeat(10)));
            status_spans.push(Span::styled(" HELP", Style::default().bg(Color::Yellow).fg(Color::Black).add_modifier(Modifier::BOLD)));
        } else {
            match app.mode {
                Mode::Normal => {
                    status_spans.push(Span::styled(" j/k ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("move "));
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("checkout "));
                    status_spans.push(Span::styled(" b ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("branch "));
                    status_spans.push(Span::styled(" f ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("fetch "));
                    status_spans.push(Span::styled(" ? ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("help "));
                    status_spans.push(Span::styled(" q ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("quit"));
                }
                Mode::Search => {
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("confirm "));
                    status_spans.push(Span::styled(" Esc ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("cancel"));
                    status_spans.push(Span::raw(" ".repeat(10)));
                    status_spans.push(Span::styled(" INPUT", Style::default().bg(Color::Yellow).fg(Color::Black).add_modifier(Modifier::BOLD)));
                }
                Mode::NewBranch => {
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("confirm "));
                    status_spans.push(Span::styled(" Esc ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("cancel"));
                    status_spans.push(Span::raw(" ".repeat(10)));
                    status_spans.push(Span::styled(" INPUT", Style::default().bg(Color::Yellow).fg(Color::Black).add_modifier(Modifier::BOLD)));
                }
                Mode::DeleteConfirm => {
                    status_spans.push(Span::styled(" Enter ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("confirm "));
                    status_spans.push(Span::styled(" Esc ", Style::default().bg(Color::Cyan).fg(Color::Black).add_modifier(Modifier::BOLD)));
                    status_spans.push(Span::raw("cancel"));
                }
            }
        }
    }

    let status_line = Line::from(status_spans);
    let status_paragraph = Paragraph::new(status_line);
    f.render_widget(status_paragraph, status_area);

    if app.help_visible {
        let area = centered_rect(60, 70, size);
        f.render_widget(Clear, area);
        let block = Block::default()
            .title(" Help ")
            .borders(Borders::ALL)
            .border_style(Style::default().fg(Color::Cyan));
        let inner = block.inner(area);
        f.render_widget(block, area);

        let help_text = vec![
            Line::from(Span::styled("Navigation", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  j / ↓      Move down"),
            Line::from("  k / ↑      Move up"),
            Line::from("  ] / Tab    Select next branch"),
            Line::from("  [ / S-Tab  Select previous branch"),
            Line::from("  h / ←      Select left branch (same commit)"),
            Line::from("  l / →      Select right branch (same commit)"),
            Line::from("  Ctrl+d     Page down"),
            Line::from("  Ctrl+u     Page up"),
            Line::from("  g / Home   Go to top"),
            Line::from("  G / End    Go to bottom"),
            Line::from("  @          Jump to HEAD (current branch)"),
            Line::from(""),
            Line::from(Span::styled("Git Operations", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  Enter      Checkout selected branch/commit"),
            Line::from("  b          Create new branch"),
            Line::from("  d          Delete branch"),
            Line::from("  f          Fetch from origin"),
            Line::from(""),
            Line::from(Span::styled("Search", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  /          Search branches"),
            Line::from("  ↑ / C-k    Select previous result"),
            Line::from("  ↓ / C-j    Select next result"),
            Line::from("  Enter      Jump to selected branch"),
            Line::from("  Esc        Cancel search"),
            Line::from(""),
            Line::from(Span::styled("Other", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))),
            Line::from("  R          Refresh"),
            Line::from("  ?          Toggle this help"),
            Line::from("  q / Esc    Quit"),
        ];
        let p = Paragraph::new(help_text);
        f.render_widget(p, inner);
    }

    match app.mode {
        Mode::Search => {
            let area = centered_rect(60, 40, size);
            f.render_widget(Clear, area);
            let block = Block::default()
                .title(" Search branches ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Cyan));
            let inner = block.inner(area);
            f.render_widget(block, area);

            let vertical = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Length(3), Constraint::Min(0)])
                .split(inner);

            let input = format!("{}_", app.search_query);
            let input_paragraph = Paragraph::new(input)
                .block(Block::default().borders(Borders::BOTTOM));
            f.render_widget(input_paragraph, vertical[0]);

            let mut items: Vec<ListItem> = Vec::new();
            for (i, branch) in app.search_results.iter().enumerate() {
                let style = if i == app.search_selected { Style::default().bg(Color::DarkGray) } else { Style::default() };
                let prefix = if i == app.search_selected { "▶ " } else { "  " };
                items.push(ListItem::new(format!("{}{}", prefix, branch.name)).style(style));
            }
            let list = ratatui::widgets::List::new(items)
                .block(Block::default().title(format!(" {} branches ", app.search_results.len())));
            f.render_widget(list, vertical[1]);
        }
        Mode::NewBranch => {
            let area = centered_rect(60, 20, size);
            f.render_widget(Clear, area);
            let block = Block::default()
                .title(" New Branch Name ")
                .borders(Borders::ALL)
                .border_style(Style::default().fg(Color::Cyan));
            let inner = block.inner(area);
            f.render_widget(block, area);

            let input = format!("{}_", app.new_branch_input);
            let vertical = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Length(3), Constraint::Length(1)])
                .split(inner);
            let p = Paragraph::new(input);
            f.render_widget(p, vertical[0]);
            let hint = Paragraph::new("  Enter: confirm  Esc: cancel");
            f.render_widget(hint, vertical[1]);
        }
        Mode::DeleteConfirm => {
            if let Some(branch) = &app.delete_confirm_branch {
                let area = centered_rect(60, 20, size);
                f.render_widget(Clear, area);
                let block = Block::default()
                    .title(" Delete Branch ")
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(Color::Red));
                let inner = block.inner(area);
                f.render_widget(block, area);

                let text = vec![
                    Line::from(format!("Delete branch '{}'?", branch.name)),
                    Line::from(""),
                    Line::from("  Enter: confirm  Esc: cancel"),
                ];
                let p = Paragraph::new(text);
                f.render_widget(p, inner);
            }
        }
        _ => {}
    }

    if app.mode == Mode::Normal && !app.help_visible {
        if !app.commits.is_empty() {
            let commit = &app.commits[app.selected_commit_idx];
            if commit.branches.len() > 1 {
                let area = Rect {
                    x: commits_area.x + commits_area.width.saturating_sub(20),
                    y: commits_area.y + 2,
                    width: 18,
                    height: (commit.branches.len() as u16 + 2).min(10),
                };
                f.render_widget(Clear, area);
                let block = Block::default()
                    .title(" Branches ")
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(Color::Cyan));
                let inner = block.inner(area);
                f.render_widget(block, area);
                let sel_idx = app.selected_branch_per_commit.get(&commit.oid).cloned().unwrap_or(0);
                let items: Vec<ListItem> = commit.branches.iter().enumerate().map(|(i, b)| {
                    let prefix = if i == sel_idx { "▶ " } else { "  " };
                    ListItem::new(format!("{}{}", prefix, b.name))
                }).collect();
                let list = ratatui::widgets::List::new(items);
                f.render_widget(list, inner);
            }
        }
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}
